308	                <div
309	                  className="h-2 rounded-full bg-blue-500 transition-all"
310	                  style={{ width: `${Math.round((splitStatus.participants.filter(p => p.paymentStatus === "paid").length / splitStatus.totalSlots) * 100)}%` }}
311	                />
