1	import { useState, useEffect } from "react";
2	import { useParams, useLocation } from "wouter";
3	import { useUser, useClerk } from "@clerk/react";
4	import { Layout } from "@/components/layout";
5	import { Button } from "@/components/ui/button";
6	import { Badge } from "@/components/ui/badge";
7	import { Input } from "@/components/ui/input";
8	import { Label } from "@/components/ui/label";
9	import { Separator } from "@/components/ui/separator";
10	import { useToast } from "@/hooks/use-toast";
11	import { Clock, MapPin, Euro, Users, CheckCircle2, AlertCircle, Loader2, LogIn, Calendar, UserX } from "lucide-react";
12	
13	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
14	const API = `${BASE}/api`;
15	
16	interface SplitBookingInfo {
17	  bookingId: number;
18	  gameId: number | null;
19	  courtName: string;
20	  facilityName: string;
21	  facilityCity: string;
22	  courtImageUrl: string | null;
23	  date: string;
24	  startTime: string;
25	  endTime: string;
26	  totalPrice: number;
27	  pricePerSlot: number;
28	  totalSlots: number;
29	  paidSlots: number;
30	  slotsLeft: number;
31	  bookingStatus: string;
32	  sport: string | null;
33	}
34	
35	export default function JoinBookingPage() {
36	  const { token } = useParams<{ token: string }>();
37	  const [, navigate] = useLocation();
38	  const { user, isSignedIn, isLoaded } = useUser();
39	  const { openSignIn } = useClerk();
40	  const { toast } = useToast();
41	
42	  const [info, setInfo] = useState<SplitBookingInfo | null>(null);
43	  const [loading, setLoading] = useState(true);
44	  const [error, setError] = useState<string | null>(null);
45	  const [joining, setJoining] = useState(false);
46	
47	  // Guest mode state
48	  const [guestMode, setGuestMode] = useState(false);
49	  const [guestName, setGuestName] = useState("");
50	  const [guestEmail, setGuestEmail] = useState("");
51	
52	  const params = new URLSearchParams(typeof window !== "undefined" ? window.location.search : "");
53	  const isPaid = params.get("paid") === "1";
54	  const isCancelled = params.get("cancelled") === "1";
55	
56	  useEffect(() => {
57	    if (!token) { setError("Nuoroda neteisinga"); setLoading(false); return; }
58	    fetch(`${API}/bookings/share/${token}`)
59	      .then(r => {
60	        if (r.status === 404) throw new Error("Kvietimo nuoroda nerasta arba nebegalioja.");
61	        if (r.status === 410) throw new Error("Rezervacija atšaukta.");
62	        if (!r.ok) throw new Error("Nepavyko gauti rezervacijos informacijos.");
63	        return r.json();
64	      })
65	      .then((data: SplitBookingInfo) => setInfo(data))
66	      .catch(err => setError(err.message))
67	      .finally(() => setLoading(false));
68	  }, [token]);
69	
70	  const handleJoin = async () => {
71	    if (!isSignedIn || !user) { openSignIn(); return; }
72	    if (!info || !token) return;
73	
74	    const email = user.primaryEmailAddress?.emailAddress ?? user.emailAddresses?.[0]?.emailAddress ?? "";
75	    const name = user.fullName || `${user.firstName ?? ""} ${user.lastName ?? ""}`.trim() || email.split("@")[0] || "Žaidėjas";
76	
77	    setJoining(true);
78	    try {
79	      const resp = await fetch(`${API}/bookings/share/${token}/checkout`, {
80	        method: "POST",
81	        headers: { "Content-Type": "application/json" },
82	        body: JSON.stringify({ playerName: name, playerEmail: email }),
83	      });
84	      if (!resp.ok) {
85	        const data = await resp.json();
86	        throw new Error(data.error ?? "Nepavyko inicijuoti mokėjimo");
87	      }
88	      const { url } = await resp.json();
89	      window.location.href = url;
90	    } catch (err: any) {
91	      toast({ title: "Klaida", description: err.message ?? "Bandykite dar kartą.", variant: "destructive" });
92	    } finally {
93	      setJoining(false);
94	    }
95	  };
96	
97	  const handleGuestJoin = async () => {
98	    if (!info || !token) return;
99	    const name = guestName.trim();
100	    const email = guestEmail.trim();
101	    if (!name || !email) {
102	      toast({ title: "Klaida", description: "Įveskite vardą ir el. paštą.", variant: "destructive" });
103	      return;
104	    }
105	
106	    setJoining(true);
107	    try {
108	      const resp = await fetch(`${API}/bookings/share/${token}/checkout`, {
109	        method: "POST",
110	        headers: { "Content-Type": "application/json" },
111	        body: JSON.stringify({ guestName: name, guestEmail: email }),
112	      });
113	      if (!resp.ok) {
114	        const data = await resp.json();
115	        throw new Error(data.error ?? "Nepavyko inicijuoti mokėjimo");
116	      }
117	      const { url } = await resp.json();
118	      window.location.href = url;
119	    } catch (err: any) {
120	      toast({ title: "Klaida", description: err.message ?? "Bandykite dar kartą.", variant: "destructive" });
121	    } finally {
122	      setJoining(false);
123	    }
124	  };
125	
126	  if (loading) {
127	    return (
128	      <Layout>
129	        <div className="max-w-md mx-auto px-4 py-16 flex flex-col items-center gap-4">
130	          <Loader2 className="w-8 h-8 animate-spin text-primary" />
131	          <p className="text-muted-foreground text-sm">Kraunama…</p>
132	        </div>
133	      </Layout>
134	    );
135	  }
136	
137	  if (error) {
138	    return (
139	      <Layout>
140	        <div className="max-w-md mx-auto px-4 py-16 flex flex-col items-center gap-4 text-center">
141	          <AlertCircle className="w-12 h-12 text-destructive" />
142	          <h1 className="text-xl font-bold">Nuoroda nebegalioja</h1>
143	          <p className="text-muted-foreground text-sm">{error}</p>
144	          <Button variant="outline" onClick={() => navigate("/")}>Grįžti į pradžią</Button>
145	        </div>
146	      </Layout>
147	    );
148	  }
149	
150	  if (!info) return null;
151	
152	  const allPaid = info.paidSlots >= info.totalSlots;
153	  const noSlotsLeft = info.slotsLeft <= 0;
154	
155	  return (
156	    <Layout>
157	      <div className="max-w-md mx-auto px-4 py-8 space-y-6">
158	
159	        {/* Success banner */}
160	        {isPaid && (
161	          <div className="flex items-center gap-3 p-4 rounded-xl bg-green-500/10 border border-green-400/20 text-green-700 dark:text-green-400">
162	            <CheckCircle2 className="w-5 h-5 shrink-0" />
163	            <div>
164	              <p className="font-semibold text-sm">Mokėjimas gautas!</p>
165	              <p className="text-xs opacity-80">Tavo dalis sėkmingai apmokėta.</p>
166	            </div>
167	          </div>
168	        )}
169	
170	        {/* Cancelled banner */}
171	        {isCancelled && (
172	          <div className="flex items-center gap-3 p-4 rounded-xl bg-yellow-500/10 border border-yellow-400/20 text-yellow-700 dark:text-yellow-400">
173	            <AlertCircle className="w-5 h-5 shrink-0" />
174	            <p className="text-sm">Mokėjimas atšauktas. Vieta kol kas laisva — galite bandyti dar kartą.</p>
175	          </div>
176	        )}
177	
178	        {/* Header */}
179	        <div>
180	          <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Mokėjimo pakvietimas</p>
181	          <h1 className="text-2xl font-bold">{info.courtName}</h1>
182	          <p className="text-muted-foreground flex items-center gap-1.5 text-sm mt-1">
183	            <MapPin className="w-3.5 h-3.5" />
184	            {info.facilityName}{info.facilityCity ? `, ${info.facilityCity}` : ""}
185	          </p>
186	        </div>
187	
188	        {/* Booking card */}
189	        <div className="rounded-2xl border bg-card shadow-sm p-5 space-y-3">
190	          {info.courtImageUrl && (
191	            <img
192	              src={info.courtImageUrl}
193	              alt={info.courtName}
194	              className="w-full h-36 object-cover rounded-xl mb-3"
195	            />
196	          )}
197	
198	          <div className="flex items-center gap-2 text-sm">
199	            <Calendar className="w-4 h-4 text-primary shrink-0" />
200	            <span className="font-medium">{info.date}</span>
201	          </div>
202	          <div className="flex items-center gap-2 text-sm">
203	            <Clock className="w-4 h-4 text-primary shrink-0" />
204	            <span className="font-medium">{info.startTime} – {info.endTime}</span>
205	          </div>
206	          {info.sport && (
207	            <div className="flex items-center gap-2 text-sm">
208	              <Users className="w-4 h-4 text-primary shrink-0" />
209	              <span className="capitalize">{info.sport}</span>
210	            </div>
211	          )}
212	
213	          <Separator />
214	
215	          {/* Slot progress */}
216	          <div className="space-y-2">
217	            <div className="flex items-center justify-between text-sm">
218	              <span className="text-muted-foreground">Apmokėta dalių</span>
219	              <span className="font-semibold">{info.paidSlots} / {info.totalSlots}</span>
220	            </div>
221	            <div className="w-full bg-muted rounded-full h-2 overflow-hidden">
222	              <div
223	                className="h-2 rounded-full bg-primary transition-all"
224	                style={{ width: `${Math.round((info.paidSlots / info.totalSlots) * 100)}%` }}
225	              />
226	            </div>
227	            <div className="flex gap-1.5 flex-wrap">
228	              {Array.from({ length: info.totalSlots }).map((_, i) => (
229	                <div
230	                  key={i}
231	                  className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center text-xs font-bold ${
232	                    i < info.paidSlots
233	                      ? "bg-primary border-primary text-primary-foreground"
234	                      : "bg-muted border-border text-muted-foreground"
235	                  }`}
236	                >
237	                  {i < info.paidSlots ? "✓" : i + 1}
238	                </div>
239	              ))}
240	            </div>
241	          </div>
242	
243	          <Separator />
244	
245	          {/* Price */}
246	          <div className="flex items-center justify-between">
247	            <div>
248	              <p className="text-xs text-muted-foreground">Jūsų dalis (1/{info.totalSlots})</p>
249	              <p className="text-2xl font-bold text-primary flex items-center gap-1">
250	                <Euro className="w-5 h-5" />{info.pricePerSlot.toFixed(2)}
251	              </p>
252	            </div>
253	            <div className="text-right">
254	              <p className="text-xs text-muted-foreground">Visa kaina</p>
255	              <p className="text-sm font-semibold">{info.totalPrice.toFixed(2)} €</p>
256	            </div>
257	          </div>
258	        </div>
259	
260	        {/* Action area */}
261	        {isPaid ? (
262	          <div className="text-center space-y-3">
263	            <p className="text-sm text-muted-foreground">
264	              {allPaid
265	                ? "Visi žaidėjai sumokėjo — rezervacija patvirtinta!"
266	                : `Laukiama likusių ${info.totalSlots - info.paidSlots} žaidėjų mokėjimo.`}
267	            </p>
268	            {isSignedIn && (
269	              <Button variant="outline" className="w-full" onClick={() => navigate("/bookings")}>
270	                Mano rezervacijos
271	              </Button>
272	            )}
273	          </div>
274	        ) : allPaid || noSlotsLeft ? (
275	          <div className="flex flex-col items-center gap-3 p-4 rounded-xl bg-muted border text-center">
276	            <CheckCircle2 className="w-8 h-8 text-muted-foreground" />
277	            <p className="text-sm text-muted-foreground font-medium">
278	              {allPaid ? "Visos dalys apmokėtos." : "Visos dalys jau užimtos."}
279	            </p>
280	          </div>
281	        ) : !isLoaded ? (
282	          <div className="h-12 w-full bg-muted rounded-xl animate-pulse" />
283	        ) : !isSignedIn ? (
284	          guestMode ? (
285	            /* Guest form */
286	            <div className="space-y-4">
287	              <p className="text-sm text-muted-foreground text-center">
288	                Įveskite savo duomenis mokėjimui. Patvirtinimas bus išsiųstas el. paštu.
289	              </p>
290	              <div className="space-y-3">
291	                <div className="space-y-1.5">
292	                  <Label htmlFor="guest-name">Vardas</Label>
293	                  <Input
294	                    id="guest-name"
295	                    placeholder="Jūsų vardas"
296	                    value={guestName}
297	                    onChange={e => setGuestName(e.target.value)}
298	                    onKeyDown={e => e.key === "Enter" && handleGuestJoin()}
299	                    autoFocus
300	                  />
301	                </div>
302	                <div className="space-y-1.5">
303	                  <Label htmlFor="guest-email">El. paštas</Label>
304	                  <Input
305	                    id="guest-email"
306	                    type="email"
307	                    placeholder="jusu@email.lt"
308	                    value={guestEmail}
309	                    onChange={e => setGuestEmail(e.target.value)}
310	                    onKeyDown={e => e.key === "Enter" && handleGuestJoin()}
311	                  />
312	                </div>
313	              </div>
314	              <Button
315	                className="button-primary w-full h-12 text-base font-semibold gap-2"
316	                onClick={handleGuestJoin}
317	                disabled={joining || !guestName.trim() || !guestEmail.trim()}
318	              >
319	                {joining ? (
320	                  <><Loader2 className="w-4 h-4 animate-spin" /> Kraunama…</>
321	                ) : (
322	                  <><Euro className="w-4 h-4" /> Mokėti {info.pricePerSlot.toFixed(2)} €</>
323	                )}
