import { sweepStalePendingGames, sweepAutoConfirmResults } from "../routes/games";
import { sweepAbandonedPendingBookings } from "../routes/bookings";
import { logger } from "./logger";

const TICK_INTERVAL_MS = 60 * 1000;

export function startCron(): void {
  let running = false;
  const tick = async () => {
    if (running) return;
    running = true;
    try {
      const [staleCount, autoCount, abandonedBookingCount] = await Promise.all([
        sweepStalePendingGames(),
        sweepAutoConfirmResults(),
        sweepAbandonedPendingBookings(),
      ]);
      if (staleCount > 0 || autoCount > 0 || abandonedBookingCount > 0) {
        logger.info({ staleCount, autoCount, abandonedBookingCount }, "cron: swept");
      }
    } catch (err) {
      logger.error({ err }, "cron tick failed");
    } finally {
      running = false;
    }
  };
  setInterval(tick, TICK_INTERVAL_MS);
  setTimeout(tick, 5000);
  logger.info({ intervalMs: TICK_INTERVAL_MS }, "cron started");
}

import { pgTable, text, boolean, timestamp, serial, integer, unique, real } from "drizzle-orm/pg-core";

export const userProfilesTable = pgTable("user_profiles", {
  userId: text("user_id").primaryKey(),
  activityPublic: boolean("activity_public").notNull().default(true),
  bio: text("bio"),
  imageUrl: text("image_url"),
  stripeAccountId: text("stripe_account_id").unique(),
  stripeAccountStatus: text("stripe_account_status").notNull().default("not_connected"),
  reliabilityScore: integer("reliability_score").notNull().default(100),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const userSportProfilesTable = pgTable("user_sport_profiles", {
  id: serial("id").primaryKey(),
  userId: text("user_id").notNull(),
  sport: text("sport").notNull(),
  level: text("level").notNull().default("beginner"),
  // Numeric skill score (e.g. NTRP 1.0–7.0 for tennis, generic 1–10)
  skillScore: real("skill_score"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => ({
  uniq: unique("user_sport_unique").on(t.userId, t.sport),
}));

export type UserProfile = typeof userProfilesTable.$inferSelect;
export type UserSportProfile = typeof userSportProfilesTable.$inferSelect;

import { pgTable, text, serial, timestamp, numeric, integer, boolean } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod/v4";

export const bookingsTable = pgTable("bookings", {
  id: serial("id").primaryKey(),
  courtId: integer("court_id").notNull(),
  bookerUserId: text("booker_user_id"),
  customerName: text("customer_name").notNull(),
  customerEmail: text("customer_email").notNull(),
  customerPhone: text("customer_phone"),
  date: text("date").notNull(), // YYYY-MM-DD
  startTime: text("start_time").notNull(), // HH:MM
  endTime: text("end_time").notNull(), // HH:MM
  totalPrice: numeric("total_price", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull().default("pending"), // pending | awaiting_players | confirmed | cancelled | blocked
  rentedItems: text("rented_items"),
  notes: text("notes"),
  stripeSessionId: text("stripe_session_id"),
  stripePaymentIntentId: text("stripe_payment_intent_id"),
  refundAmount: numeric("refund_amount", { precision: 10, scale: 2 }).notNull().default("0"),
  stripeRefundId: text("stripe_refund_id"),
  // Opaque token allowing a guest (no Clerk session) to view & cancel their booking.
  managementToken: text("management_token").unique(),
  // Split payment fields
  isSplit: boolean("is_split").notNull().default(false),
  totalSlots: integer("total_slots"),
  pricePerSlot: numeric("price_per_slot", { precision: 10, scale: 2 }),
  splitInviteToken: text("split_invite_token").unique(),
  // Smart lock access code (delivered post-payment)
  accessCode: text("access_code"),
  // Recurring booking group (null = one-off, uuid string = part of a weekly series)
  recurringGroupId: text("recurring_group_id"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const insertBookingSchema = createInsertSchema(bookingsTable).omit({ id: true, createdAt: true });
export type InsertBooking = z.infer<typeof insertBookingSchema>;
export type Booking = typeof bookingsTable.$inferSelect;

import { pgTable, text, serial, timestamp, integer, boolean, jsonb, real } from "drizzle-orm/pg-core";
import { bookingsTable } from "./bookings";

export const gamesTable = pgTable("games", {
  id: serial("id").primaryKey(),
  creatorUserId: text("creator_user_id").notNull(),
  creatorName: text("creator_name").notNull(),
  creatorEmail: text("creator_email"),
  sport: text("sport").notNull(),
  city: text("city").notNull(),
  placeName: text("place_name"),
  facilityId: integer("facility_id"),
  courtId: integer("court_id"),
  bookingId: integer("booking_id").references(() => bookingsTable.id, { onDelete: "set null" }),
  playersNeeded: integer("players_needed").notNull().default(4),
  skillLevel: text("skill_level").notNull().default("any"),
  datetime: text("datetime").notNull(),
  durationMinutes: integer("duration_minutes").notNull().default(60),
  description: text("description"),
  // status values: pending_payment | awaiting_players | open | full | pending_verification | completed | disputed | cancelling
  status: text("status").notNull().default("open"),
  matchType: text("match_type").notNull().default("casual"),
  isPrivate: boolean("is_private").notNull().default(false),
  // visibility: 'private' (invite-only via token) | 'public' (shown on open matches feed)
  visibility: text("visibility").notNull().default("private"),
  minSkillLevel: real("min_skill_level"),
  maxSkillLevel: real("max_skill_level"),
  requiresApproval: boolean("requires_approval").notNull().default(false),
  teamCount: integer("team_count").notNull().default(2),
  inviteToken: text("invite_token"),
  // Sport-specific structured score (SetScore[] for SET_BASED, {a,b} for POINT_BASED).
  resultData: jsonb("result_data"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const gameParticipantsTable = pgTable("game_participants", {
  id: serial("id").primaryKey(),
  gameId: integer("game_id").notNull().references(() => gamesTable.id, { onDelete: "cascade" }),
  userId: text("user_id"),
  userName: text("user_name").notNull(),
  userEmail: text("user_email"),
  team: text("team"),
  status: text("status").notNull().default("joined"),
  // "join_request" = user asked to join; "invite" = creator invited user (requires user acceptance)
  source: text("source").notNull().default("join_request"),
  // Split-payment tracking
  paymentStatus: text("payment_status").notNull().default("paid"), // paid | pending
  stripeSessionId: text("stripe_session_id"),
  inviteEmail: text("invite_email"),
  joinedAt: timestamp("joined_at", { withTimezone: true }).notNull().defaultNow(),
});

export const gameChatTable = pgTable("game_chat", {
  id: serial("id").primaryKey(),
  gameId: integer("game_id").notNull().references(() => gamesTable.id, { onDelete: "cascade" }),
  senderUserId: text("sender_user_id").notNull(),
  senderName: text("sender_name").notNull(),
  body: text("body").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type Game = typeof gamesTable.$inferSelect;
export type GameParticipant = typeof gameParticipantsTable.$inferSelect;
export type GameChat = typeof gameChatTable.$inferSelect;

