50	  const [joining, setJoining] = useState(false);
51	
52	  // Guest mode state
53	  const [guestMode, setGuestMode] = useState(false);
54	  const [guestName, setGuestName] = useState("");
55	  const [guestEmail, setGuestEmail] = useState("");
56	
57	  const params = new URLSearchParams(typeof window !== "undefined" ? window.location.search : "");
58	  const isPaid = params.get("paid") === "1";
59	  const isCancelled = params.get("cancelled") === "1";
60	
61	  useEffect(() => {
62	    if (!token) { setError("Nuoroda neteisinga"); setLoading(false); return; }
63	    fetch(`${API}/bookings/share/${token}`)
64	      .then(r => {
65	        if (r.status === 404) throw new Error("Kvietimo nuoroda nerasta arba nebegalioja.");
66	        if (r.status === 410) throw new Error("Rezervacija atšaukta.");
67	        if (!r.ok) throw new Error("Nepavyko gauti rezervacijos informacijos.");
68	        return r.json();
69	      })
70	      .then(async (data: SplitBookingInfo) => {
71	        setInfo(data);
72	        if (data.courtId) {
73	          const courtRes = await fetch(`${API}/courts/${data.courtId}`).catch(() => null);
74	          if (courtRes?.ok) {
75	            const c = await courtRes.json();
76	            setCourtAddress({ address: c.address ?? null, city: c.city ?? null });
77	          }
78	        }
79	      })
80	      .catch(err => setError(err.message))
81	      .finally(() => setLoading(false));
82	  }, [token]);
83	
84	  const handleJoin = async () => {
85	    if (!isSignedIn || !user) { openSignIn(); return; }
86	    if (!info || !token) return;
87	
88	    const email = user.primaryEmailAddress?.emailAddress ?? user.emailAddresses?.[0]?.emailAddress ?? "";
89	    const name = user.fullName || `${user.firstName ?? ""} ${user.lastName ?? ""}`.trim() || email.split("@")[0] || "Žaidėjas";
90	
91	    setJoining(true);
92	    try {
93	      const resp = await fetch(`${API}/bookings/share/${token}/checkout`, {
94	        method: "POST",
95	        headers: { "Content-Type": "application/json" },
96	        body: JSON.stringify({ playerName: name, playerEmail: email }),
97	      });
98	      if (!resp.ok) {
99	        const data = await resp.json();
100	        throw new Error(data.error ?? "Nepavyko inicijuoti mokėjimo");
101	      }
102	      const { url } = await resp.json();
103	      window.location.href = url;
104	    } catch (err: any) {
105	      toast({ title: "Klaida", description: err.message ?? "Bandykite dar kartą.", variant: "destructive" });
106	    } finally {
107	      setJoining(false);
108	    }
109	  };
110	
111	  const handleGuestJoin = async () => {
112	    if (!info || !token) return;
113	    const name = guestName.trim();
114	    const email = guestEmail.trim();
115	    if (!name || !email) {
116	      toast({ title: "Klaida", description: "Įveskite vardą ir el. paštą.", variant: "destructive" });
117	      return;
118	    }
119	
120	    setJoining(true);
121	    try {
122	      const resp = await fetch(`${API}/bookings/share/${token}/checkout`, {
123	        method: "POST",
124	        headers: { "Content-Type": "application/json" },
125	        body: JSON.stringify({ guestName: name, guestEmail: email }),
126	      });
127	      if (!resp.ok) {
128	        const data = await resp.json();
129	        throw new Error(data.error ?? "Nepavyko inicijuoti mokėjimo");
130	      }
