132	      window.location.href = url;
133	    } catch (err: any) {
134	      toast({ title: "Klaida", description: err.message ?? "Bandykite dar kartą.", variant: "destructive" });
135	    } finally {
136	      setJoining(false);
137	    }
138	  };
139	
140	  if (loading) {
141	    return (
142	      <Layout>
