146	        </div>
147	      </Layout>
148	    );
149	  }
150	
151	  if (error) {
152	    return (
153	      <Layout>
154	        <div className="max-w-md mx-auto px-4 py-16 flex flex-col items-center gap-4 text-center">
155	          <AlertCircle className="w-12 h-12 text-destructive" />
156	          <h1 className="text-xl font-bold">Nuoroda nebegalioja</h1>
157	          <p className="text-muted-foreground text-sm">{error}</p>
158	          <Button variant="outline" onClick={() => navigate("/")}>Grįžti į pradžią</Button>
159	        </div>
160	      </Layout>
161	    );
162	  }
163	
164	  if (!info) return null;
165	
166	  const allPaid = info.paidSlots >= info.totalSlots;
167	  const noSlotsLeft = info.slotsLeft <= 0;
168	
169	  return (
