171	      <div className="max-w-md mx-auto px-4 py-8 space-y-6">
172	
173	        {/* Success banner */}
174	        {isPaid && (
175	          <div className="flex items-center gap-3 p-4 rounded-xl bg-green-500/10 border border-green-400/20 text-green-700 dark:text-green-400">
176	            <CheckCircle2 className="w-5 h-5 shrink-0" />
177	            <div>
