const rows = await query;

// For split bookings, fetch paid-slot counts in a single batch query
const splitBookingIds = rows.filter(r => r.booking.isSplit).map(r => r.booking.id);
const paidSlotsMap = new Map<number, number>();
if (splitBookingIds.length > 0) {
  const gameRows = await db
    .select({ bookingId: gamesTable.bookingId, gameId: gamesTable.id })
    .from(gamesTable)
    .where(inArray(gamesTable.bookingId, splitBookingIds));
  const gameIds = gameRows.map(g => g.gameId);
  if (gameIds.length > 0) {
    const countRows = await db
      .select({ gameId: gameParticipantsTable.gameId, paid: count() })
      .from(gameParticipantsTable)
      .where(and(
        inArray(gameParticipantsTable.gameId, gameIds),
        eq(gameParticipantsTable.status, "joined"),
        eq(gameParticipantsTable.paymentStatus, "paid"),
      ))
      .groupBy(gameParticipantsTable.gameId);
    for (const row of countRows) {
      const game = gameRows.find(g => g.gameId === row.gameId);
      if (game?.bookingId != null) paidSlotsMap.set(game.bookingId, Number(row.paid));
    }
  }
}

res.json(ListBookingsResponse.parse(rows.map(r => formatBooking(r.booking, r.courtName ?? undefined, paidSlotsMap.get(r.booking.id)))));

