// For split bookings, count paid participants (matches the split-status endpoint logic)
const splitBookingIds = rows.filter(r => r.booking.isSplit).map(r => r.booking.id);
const paidSlotsMap = new Map<number, number>();
if (splitBookingIds.length > 0) {
  const gameRows = await db
    .select({ bookingId: gamesTable.bookingId, gameId: gamesTable.id })
    .from(gamesTable)
    .where(inArray(gamesTable.bookingId, splitBookingIds));

  const bookingIdByGameId = new Map<number, number>();
  for (const g of gameRows) {
    if (g.bookingId != null) bookingIdByGameId.set(g.gameId, g.bookingId);
  }

  if (gameRows.length > 0) {
    const allParticipants = await db
      .select({ gameId: gameParticipantsTable.gameId, paymentStatus: gameParticipantsTable.paymentStatus })
      .from(gameParticipantsTable)
      .where(and(
        inArray(gameParticipantsTable.gameId, gameRows.map(g => g.gameId)),
        eq(gameParticipantsTable.status, "joined"),
      ));

    for (const p of allParticipants) {
      if (p.paymentStatus !== "paid") continue;
      const bookingId = bookingIdByGameId.get(p.gameId);
      if (bookingId != null) {
        paidSlotsMap.set(bookingId, (paidSlotsMap.get(bookingId) ?? 0) + 1);
      }
    }
  }
}

