    paidSlots?: number;
    ```

- **`artifacts/courtbook/src/pages/bookings.tsx`**
  - Added `paidSlots?: number` to `BookingItem` type
  - Added `useEffect` import
  - Added `useCountdown` hook:
    ```typescript
    function useCountdown(targetMs: number | null): string | null {
      const [label, setLabel] = useState<string | null>(null);
      useEffect(() => {
        if (targetMs === null) return;
        const update = () => {
          const diff = targetMs - Date.now();
          if (diff <= 0) { setLabel("Laikas baigėsi"); return; }
          const h = Math.floor(diff / 3600000);
          const m = Math.floor((diff % 3600000) / 60000);
          const s = Math.floor((diff % 60000) / 1000);
          if (h > 0) setLabel(`${h} val. ${m} min.`);
          else if (m > 0) setLabel(`${m} min. ${s} sek.`);
          else setLabel(`${s} sek.`);
        };
        update();
        const id = setInterval(update, 1000);
        return () => clearInterval(id);
      }, [targetMs]);
      return label;
    }
    ```
  - Fixed `startMs` (was causing past bookings to show in upcoming):
    ```typescript
    const startMs = (b: typeof sorted[number]) => {
      const dateStr = format(b.date, "yyyy-MM-dd");
      const time = b.endTime ?? b.startTime ?? "00:00";
      return new Date(`${dateStr}T${time}:00`).getTime();
    };
    ```
  - Split badge updated: `${booking.paidSlots ?? 0}/${booking.totalSlots} apmokėta`
  - Countdown in split badge for `awaiting_players`

- **`artifacts/courtbook/src/pages/booking-detail.tsx`**
  - Added `useCountdown` hook (same implementation)
  - Added guarantee deadline + countdown:
    ```typescript
    const guaranteeDeadlineMs = (booking?.isSplit && booking.status === "awaiting_players" && booking.date && booking.startTime)
      ? new Date(`${booking.date.split("T")[0]}T${booking.startTime}:00`).getTime() - 2 * 60 * 60 * 1000
      : null;
    const countdown = useCountdown(guaranteeDeadlineMs);
    ```
  - Countdown row in split panel (amber, above share link)

- **`artifacts/courtbook/src/pages/court-detail.tsx`**
  - Added `isLastMinute` useMemo + useEffect to auto-disable split toggle:
    ```typescript
    const isLastMinute = useMemo(() => {
      if (!selectedSlotRange) return false;
      const gameStart = new Date(`${dateStr}T${selectedSlotRange.startTime}:00`);
      return gameStart.getTime() - Date.now() < 2 * 60 * 60 * 1000;
    }, [selectedSlotRange, dateStr]);
    useEffect(() => {
      if (isLastMinute) setSplitEnabled(false);
