115	  // ── Server-side price calculation ─────────────────────────────────────────
116	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
117	  const { priceMap } = await buildDayPriceMap(courtId, date, defaultSlotPrice);
118	
119	  const slots = slotsBetween(startTime, endTime);
120	  let courtPrice = 0;
121	  for (const slotStart of slots) {
122	    courtPrice += priceMap.get(slotStart) ?? defaultSlotPrice;
123	  }
124	
125	  const totalPrice = courtPrice;
126	  const pricePerSlot = Math.round((totalPrice / totalSlots) * 100) / 100;
