143	      eq(bookingsTable.courtId, courtId),
144	      eq(bookingsTable.date, date),
145	      eq(bookingsTable.status, "pending"),
146	      sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`,
147	    ));
148	
149	  const allConflicting = [...conflictingBookings, ...recentPending];
150	  for (const b of allConflicting) {
151	    const bStart = toMin(b.startTime);
152	    const bEnd = toMin(b.endTime);
153	    if (reqStartMin < bEnd && reqEndMin > bStart) {
154	      res.status(409).json({ error: "Pasirinktas laikas užimtas", code: "SLOT_UNAVAILABLE" });
