161	    .select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
162	    .from(courtBlockedSlotsTable)
163	    .where(and(
164	      eq(courtBlockedSlotsTable.courtId, courtId),
165	      eq(courtBlockedSlotsTable.date, date),
166	    ));
167	
168	  for (const b of blockedSlots) {
169	    const bStart = toMin(b.startTime);
170	    const bEnd = toMin(b.endTime);
171	    if (reqStartMin < bEnd && reqEndMin > bStart) {
172	      res.status(409).json({ error: "Pasirinktas laikas užblokuotas", code: "SLOT_BLOCKED" });
173	      return;
174	    }
175	  }
176	
177	  // ── Create booking ────────────────────────────────────────────────────────
178	  const splitInviteToken = crypto.randomBytes(20).toString("hex");
179	  const datetime = `${date}T${startTime}:00`;
180	
181	  const [booking] = await db.insert(bookingsTable).values({
182	    courtId,
183	    bookerUserId: userId,
184	    customerName,
185	    customerEmail,
186	    customerPhone: customerPhone ?? null,
