578	router.get("/bookings/share/:token", async (req, res): Promise<void> => {
579	  const token = String(req.params.token);
580	  if (!token) { res.status(400).json({ error: "Token required" }); return; }
581	
582	  const rows = await db
583	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
584	    .from(bookingsTable)
585	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
586	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
587	    .where(eq(bookingsTable.splitInviteToken, token));
