621	  const slotsLeft = Math.max(0, (booking.totalSlots ?? 1) - paidCount - pendingCount);
622	
623	  // Guarantee deadline: game start - 2 hours (game time is stored as Vilnius local)
624	  const GUARANTEE_HOURS = 2;
625	  const gameStartMs = vilniusLocalToUtcMs(booking.date.split("T")[0], booking.startTime);
