628	  res.json({
629	    bookingId: booking.id,
630	    gameId: game?.id ?? null,
631	    courtId: court?.id ?? null,
632	    courtName: court?.name ?? "",
633	    facilityName: facility?.name ?? "",
634	    facilityAddress: facility?.address ?? null,
635	    facilityCity: facility?.city ?? "",
636	    courtImageUrl: court?.imageUrl ?? null,
637	    date: booking.date,
638	    startTime: booking.startTime,
639	    endTime: booking.endTime,
640	    totalPrice: Number(booking.totalPrice),
641	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
642	    totalSlots: booking.totalSlots ?? 1,
643	    paidSlots: paidCount,
644	    slotsLeft,
645	    bookingStatus: booking.status,
646	    sport: game?.sport ?? null,
647	    paidParticipants: paidParticipantNames,
648	    guaranteeDeadline,
