657	
658	  // Guests must supply name + email
659	  const isGuest = !userId;
660	  let guestName: string | null = null;
661	  let guestEmail: string | null = null;
662	  if (isGuest) {
663	    guestName = (req.body?.guestName as string | undefined)?.trim() ?? null;
664	    guestEmail = (req.body?.guestEmail as string | undefined)?.trim() ?? null;
665	    if (!guestName || !guestEmail) {
666	      res.status(400).json({ error: "Vardas ir el. paštas privalomi" });
667	      return;
668	    }
669	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(guestEmail)) {
670	      res.status(400).json({ error: "Neteisingas el. pašto adresas" });
671	      return;
672	    }
673	  }
674	
675	  const rows = await db
676	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
677	    .from(bookingsTable)
678	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
679	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
680	    .where(eq(bookingsTable.splitInviteToken, token));
681	
682	  if (!rows[0]) { res.status(404).json({ error: "Invite link not found" }); return; }
683	
684	  const { booking, court, facility } = rows[0];
685	
686	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
687	  if (booking.status === "cancelled") { res.status(410).json({ error: "Booking was cancelled" }); return; }
688	  if (booking.status === "confirmed") { res.status(409).json({ error: "Booking fully paid" }); return; }
689	
690	  // Reject payments once the game has already started (time stored as Vilnius local)
691	  const gameStartMs = vilniusLocalToUtcMs(booking.date.split("T")[0], booking.startTime);
692	  if (Date.now() >= gameStartMs) {
693	    res.status(410).json({ error: "Žaidimo laikas jau praėjo — mokėti nebegalima" });
694	    return;
695	  }
696	
697	  // Prevent authenticated host from joining again via invite link
698	  if (!isGuest && booking.bookerUserId === userId) {
699	    res.status(409).json({ error: "Tu jau esi šio žaidimo organizatorius" });
700	    return;
701	  }
702	
703	  // Get linked game
704	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, booking.id));
705	  if (!game) { res.status(500).json({ error: "Game not found" }); return; }
706	
707	  // Get existing participants
708	  const existingParticipants = await db
709	    .select()
710	    .from(gameParticipantsTable)
711	    .where(and(
712	      eq(gameParticipantsTable.gameId, game.id),
713	      eq(gameParticipantsTable.status, "joined"),
714	    ));
715	
716	  // Skill level gate for public matches (authenticated users only)
717	  if (!isGuest && userId && game.visibility === "public" && (game.minSkillLevel != null || game.maxSkillLevel != null)) {
718	    const [sportProfile] = await db
719	      .select({ skillScore: userSportProfilesTable.skillScore })
720	      .from(userSportProfilesTable)
721	      .where(and(
722	        eq(userSportProfilesTable.userId, userId),
723	        eq(userSportProfilesTable.sport, game.sport),
724	      ));
725	
726	    const userSkill = sportProfile?.skillScore ?? null;
727	    if (userSkill != null) {
728	      if (game.minSkillLevel != null && userSkill < game.minSkillLevel) {
729	        res.status(403).json({ error: "Jūsų lygis per žemas šiam žaidimui", code: "SKILL_TOO_LOW" });
730	        return;
731	      }
732	      if (game.maxSkillLevel != null && userSkill > game.maxSkillLevel) {
733	        res.status(403).json({ error: "Jūsų lygis per aukštas šiam žaidimui", code: "SKILL_TOO_HIGH" });
734	        return;
735	      }
736	    }
737	  }
738	
739	  // Check if authenticated user already has a slot (paid or pending)
740	  if (!isGuest) {
741	    const alreadyJoined = existingParticipants.find(p => p.userId === userId);
742	    if (alreadyJoined) {
743	      if (alreadyJoined.paymentStatus === "paid") {
744	        res.status(409).json({ error: "Tu jau sumokėjai savo dalį" });
745	      } else {
746	        res.status(409).json({ error: "Turi laukiančią mokėjimo sesiją. Užbaik mokėjimą arba bandyk vėliau." });
747	      }
748	      return;
749	    }
750	  }
751	
752	  const pricePerSlot = Number(booking.pricePerSlot ?? 0);
753	
754	  const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
755	  const base = process.env.BASE_PATH ?? "";
756	
757	  const userName = isGuest ? guestName! : ((req.body?.playerName as string | undefined) ?? "Žaidėjas");
758	  const userEmail = isGuest ? guestEmail! : ((req.body?.playerEmail as string | undefined) ?? "");
759	
760	  const successUrl = `${origin}${base}/join/${token}?paid=1`;
761	  const cancelUrl = `${origin}${base}/join/${token}?cancelled=1`;
762	
763	  // Atomic capacity check + insert inside a transaction to prevent TOCTOU race conditions.
764	  // The FOR UPDATE lock on the booking row serializes concurrent join requests.
765	  let participant: typeof gameParticipantsTable.$inferSelect;
766	  try {
767	    participant = await db.transaction(async (tx) => {
768	      await tx.execute(sql`SELECT id FROM bookings WHERE id = ${booking.id} FOR UPDATE`);
769	
770	      const freshParticipants = await tx
771	        .select()
772	        .from(gameParticipantsTable)
773	        .where(and(
774	          eq(gameParticipantsTable.gameId, game.id),
775	          eq(gameParticipantsTable.status, "joined"),
776	        ));
777	
778	      if (!isGuest) {
779	        const alreadyJoined = freshParticipants.find(p => p.userId === userId);
780	        if (alreadyJoined) {
781	          const code = alreadyJoined.paymentStatus === "paid" ? "ALREADY_PAID" : "PENDING_PAYMENT";
782	          throw Object.assign(new Error("conflict"), { txCode: code });
783	        }
784	      }
785	
786	      if (freshParticipants.length >= (booking.totalSlots ?? 1)) {
787	        throw Object.assign(new Error("slots_full"), { txCode: "SLOTS_FULL" });
788	      }
789	
790	      const [newParticipant] = await tx.insert(gameParticipantsTable).values({
791	        gameId: game.id,
792	        userId: isGuest ? null : userId,
793	        userName,
794	        userEmail: userEmail || null,
795	        status: "joined",
796	        source: "join_request",
797	        paymentStatus: "pending",
798	      }).returning();
799	
800	      return newParticipant;
801	    });
802	  } catch (err: any) {
803	    if (err?.txCode === "SLOTS_FULL") {
804	      res.status(409).json({ error: "Visos dalys jau užimtos" });
805	      return;
806	    }
807	    if (err?.txCode === "ALREADY_PAID") {
808	      res.status(409).json({ error: "Tu jau sumokėjai savo dalį" });
809	      return;
810	    }
811	    if (err?.txCode === "PENDING_PAYMENT") {
812	      res.status(409).json({ error: "Turi laukiančią mokėjimo sesiją. Užbaik mokėjimą arba bandyk vėliau." });
813	      return;
814	    }
815	    throw err;
816	  }
817	
818	  let checkoutUrl: string;
819	  try {
820	    const stripe = await getUncachableStripeClient();
821	
822	    let connectAccountId: string | null = null;
823	    if (facility?.ownerUserId) {
824	      const [ownerProfile] = await db
825	        .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
826	        .from(userProfilesTable)
827	        .where(eq(userProfilesTable.userId, facility.ownerUserId));
828	      if (ownerProfile?.stripeAccountId && ownerProfile.status === "active") {
829	        connectAccountId = ownerProfile.stripeAccountId;
830	      }
831	    }
832	
833	    const amountCents = Math.round(pricePerSlot * 100);
834	    const slotNumber = existingParticipants.length + 1;
835	    const sessionParams: any = {
836	      payment_method_types: ["card"],
837	      line_items: [{
838	        price_data: {
839	          currency: "eur",
840	          product_data: {
841	            name: `${court?.name ?? "Kortas"} – mokėjimo dalis (${slotNumber}/${booking.totalSlots})`,
842	            description: `${booking.date} · ${booking.startTime}–${booking.endTime}`,
843	          },
844	          unit_amount: amountCents,
845	        },
846	        quantity: 1,
847	      }],
848	      mode: "payment",
849	      success_url: `${successUrl}&session_id={CHECKOUT_SESSION_ID}`,
850	      cancel_url: cancelUrl,
851	      metadata: {
852	        bookingId: String(booking.id),
853	        splitParticipantId: String(participant.id),
854	      },
855	      customer_email: userEmail || undefined,
856	      locale: "lt",
857	    };
858	
859	    if (connectAccountId) {
860	      const feeAmount = Math.round(amountCents * 5 / 100);
861	      sessionParams.payment_intent_data = {
862	        application_fee_amount: feeAmount,
863	        transfer_data: { destination: connectAccountId },
864	      };
865	    }
866	
867	    const session = await stripe.checkout.sessions.create(sessionParams);
868	
869	    await db.update(gameParticipantsTable)
870	      .set({ stripeSessionId: session.id })
871	      .where(eq(gameParticipantsTable.id, participant.id));
872	
873	    checkoutUrl = session.url!;
874	
875	  } catch (err: any) {
876	    if (err?.message?.includes("Stripe not configured") || err?.type === "StripeAuthenticationError") {
877	      const mockId = `mock_split_join_${booking.id}_${Date.now()}`;
878	      await db.update(gameParticipantsTable)
879	        .set({ paymentStatus: "paid", stripeSessionId: mockId })
880	        .where(eq(gameParticipantsTable.id, participant.id));
881	
882	      // Check if all paid
883	      const allParticipants = await db
884	        .select({ paymentStatus: gameParticipantsTable.paymentStatus })
885	        .from(gameParticipantsTable)
886	        .where(and(eq(gameParticipantsTable.gameId, game.id), eq(gameParticipantsTable.status, "joined")));
887	      const paidCount = allParticipants.filter(p => p.paymentStatus === "paid").length;
888	
889	      if (paidCount >= (booking.totalSlots ?? 1)) {
890	        await db.update(bookingsTable).set({ status: "confirmed" }).where(eq(bookingsTable.id, booking.id));
891	        await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, game.id));
892	      }
893	
894	      // Notify host that someone joined
895	      if (booking.bookerUserId) {
896	        sendNotification(
897	          booking.bookerUserId,
898	          "split_player_joined",
899	          `${userName} prisijungė prie jūsų žaidimo!`,
900	          `Apmokėta: ${paidCount}/${booking.totalSlots ?? 1} vietų – ${court?.name ?? "kortas"}, ${booking.date}`,
901	          `/bookings/${booking.id}`,
902	        ).catch(() => {});
903	
904	        sendSplitPlayerJoinedEmail({
905	          hostName: booking.customerName,
906	          hostEmail: booking.customerEmail,
907	          playerName: userName,
908	          courtName: court?.name ?? "Kortas",
909	          date: booking.date,
910	          startTime: booking.startTime,
911	          endTime: booking.endTime,
912	          paidSlots: paidCount,
913	          totalSlots: booking.totalSlots ?? 1,
914	          bookingId: booking.id,
915	        }).catch((e) => logger.error({ e }, "sendSplitPlayerJoinedEmail failed"));
916	      }
917	
918	      // Send confirmation to the invitee
919	      if (userEmail) {
920	        sendSplitParticipantConfirmationEmail({
921	          playerName: userName,
922	          playerEmail: userEmail,
923	          courtName: court?.name ?? "Kortas",
924	          courtId: booking.courtId,
925	          date: booking.date,
926	          startTime: booking.startTime,
927	          endTime: booking.endTime,
928	          pricePerSlot: pricePerSlot,
929	          bookingId: booking.id,
930	        }).catch((e) => logger.error({ e }, "sendSplitParticipantConfirmationEmail failed"));
931	      }
932	
933	      checkoutUrl = `${successUrl}&session_id=${mockId}`;
934	    } else {
935	      logger.error({ err }, "Failed to create Stripe session for split participant");
936	      res.status(500).json({ error: "Failed to create payment session" });
937	      return;
938	    }
939	  }
940	
941	  res.json({ url: checkoutUrl });
942	});
