944	// ─── GET /api/bookings/:bookingId/split-status ────────────────────────────────
945	
946	router.get("/bookings/:bookingId/split-status", requireAuth, async (req, res): Promise<void> => {
947	  const userId = getCurrentUserId(req)!;
948	  const bookingId = parseInt(String(req.params.bookingId), 10);
949	  if (isNaN(bookingId)) { res.status(400).json({ error: "Invalid bookingId" }); return; }
950	
951	  const [booking] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, bookingId));
952	  if (!booking) { res.status(404).json({ error: "Booking not found" }); return; }
953	
954	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
955	
956	  // Auth: must be the host
957	  if (booking.bookerUserId !== userId) {
958	    // Or a participant
959	    const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, bookingId));
960	    if (!game) { res.status(403).json({ error: "Forbidden" }); return; }
961	    const [p] = await db.select({ id: gameParticipantsTable.id })
962	      .from(gameParticipantsTable)
963	      .where(and(
964	        eq(gameParticipantsTable.gameId, game.id),
965	        eq(gameParticipantsTable.userId, userId),
966	      ));
967	    if (!p) { res.status(403).json({ error: "Forbidden" }); return; }
968	  }
969	
970	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, bookingId));
971	
972	  const participants = game
973	    ? await db.select().from(gameParticipantsTable)
974	        .where(and(eq(gameParticipantsTable.gameId, game.id), eq(gameParticipantsTable.status, "joined")))
975	    : [];
976	
977	  res.json({
978	    bookingId,
979	    gameId: game?.id ?? null,
980	    bookingStatus: booking.status,
981	    totalSlots: booking.totalSlots ?? 1,
982	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
983	    totalPrice: Number(booking.totalPrice),
984	    shareToken: booking.splitInviteToken,
985	    participants: participants.map(p => ({
986	      userId: p.userId,
987	      userName: p.userName,
988	      paymentStatus: p.paymentStatus,
989	      joinedAt: p.joinedAt.toISOString(),
990	    })),
991	  });
992	});
993	
994	export default router;
995	
996	// ─── sweepHostGuarantees ──────────────────────────────────────────────────────
997	// Runs periodically. Finds awaiting_players split bookings whose game starts
998	// within GUARANTEE_HOURS. Charges the host's saved card for the missing amount.
999	// On success → confirmed. On failure → cancelled + refund all paid participants.
1000	
1001	const GUARANTEE_HOURS = 2;
1002	
1003	export async function sweepHostGuarantees(): Promise<number> {
1004	  // Find split bookings in awaiting_players whose game starts within the guarantee window
1005	  const candidates = await db
1006	    .select({
1007	      booking: bookingsTable,
1008	      game: gamesTable,
1009	    })
1010	    .from(bookingsTable)
1011	    .innerJoin(gamesTable, eq(gamesTable.bookingId, bookingsTable.id))
1012	    .where(
1013	      and(
1014	        eq(bookingsTable.status, "awaiting_players"),
1015	        eq(bookingsTable.isSplit, true),
1016	        // Only bookings where we have a saved payment method for the host
1017	        sql`${bookingsTable.hostStripeCustomerId} IS NOT NULL`,
1018	        sql`${bookingsTable.hostStripePaymentMethodId} IS NOT NULL`,
1019	        // Game starts within the next GUARANTEE_HOURS (deadline reached)
1020	        sql`CAST(${gamesTable.datetime} AS TIMESTAMPTZ) <= NOW() + INTERVAL '${sql.raw(String(GUARANTEE_HOURS))} hours'`,
1021	        // Game hasn't ended yet (don't process historical bookings)
1022	        sql`CAST(${gamesTable.datetime} AS TIMESTAMPTZ) > NOW() - INTERVAL '3 hours'`,
1023	      ),
1024	    );
1025	
1026	  if (candidates.length === 0) return 0;
1027	
1028	  let processed = 0;
1029	  const stripe = await getUncachableStripeClient().catch(() => null);
1030	  if (!stripe) return 0; // Stripe not configured; skip in dev
1031	
1032	  for (const { booking, game } of candidates) {
1033	    try {
1034	      // Get all participants for this game
1035	      const participants = await db
1036	        .select()
1037	        .from(gameParticipantsTable)
1038	        .where(and(
1039	          eq(gameParticipantsTable.gameId, game.id),
1040	          eq(gameParticipantsTable.status, "joined"),
1041	        ));
1042	
1043	      const paidCount = participants.filter(p => p.paymentStatus === "paid").length;
1044	      const totalSlots = booking.totalSlots ?? 1;
1045	      const pricePerSlot = Number(booking.pricePerSlot ?? 0);
1046	      const missingSlots = Math.max(0, totalSlots - paidCount);
1047	
1048	      if (missingSlots === 0) {
1049	        // All paid — just confirm
1050	        await db.update(bookingsTable).set({ status: "confirmed" }).where(eq(bookingsTable.id, booking.id));
1051	        await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, game.id));
1052	        processed++;
1053	        continue;
1054	      }
1055	
1056	      const missingAmountCents = Math.round(missingSlots * pricePerSlot * 100);
1057	
1058	      // Fetch Connect account if applicable
1059	      let transferData: { destination: string } | undefined;
1060	      let appFeeAmount: number | undefined;
1061	      const courtRows = await db
1062	        .select({ facilityId: courtsTable.facilityId })
1063	        .from(courtsTable)
1064	        .where(eq(courtsTable.id, booking.courtId));
1065	      const facilityId = courtRows[0]?.facilityId;
1066	      if (facilityId) {
1067	        const [fac] = await db
1068	          .select({ ownerUserId: facilitiesTable.ownerUserId })
1069	          .from(facilitiesTable)
1070	          .where(eq(facilitiesTable.id, facilityId));
1071	        if (fac?.ownerUserId) {
1072	          const [profile] = await db
1073	            .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
1074	            .from(userProfilesTable)
1075	            .where(eq(userProfilesTable.userId, fac.ownerUserId));
1076	          if (profile?.stripeAccountId && profile.status === "active") {
1077	            transferData = { destination: profile.stripeAccountId };
1078	            appFeeAmount = Math.round(missingAmountCents * 5 / 100);
1079	          }
1080	        }
1081	      }
1082	
1083	      try {
1084	        await stripe.paymentIntents.create({
1085	          amount: missingAmountCents,
1086	          currency: "eur",
1087	          customer: booking.hostStripeCustomerId!,
1088	          payment_method: booking.hostStripePaymentMethodId!,
1089	          confirm: true,
1090	          off_session: true,
1091	          ...(transferData ? { transfer_data: transferData, application_fee_amount: appFeeAmount } : {}),
1092	        }, {
1093	          idempotencyKey: `guarantee-booking-${booking.id}`,
1094	        });
1095	
1096	        // Charge succeeded → confirm
1097	        await db.update(bookingsTable).set({ status: "confirmed" }).where(eq(bookingsTable.id, booking.id));
1098	        await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, game.id));
1099	        logger.info({ bookingId: booking.id, missingAmountCents }, "guarantee charge succeeded");
1100	        processed++;
1101	      } catch (chargeErr: any) {
1102	        // Charge failed → cancel and refund paid participants
1103	        logger.warn({ bookingId: booking.id, err: chargeErr?.message }, "guarantee charge failed — cancelling");
1104	        await db.update(bookingsTable).set({ status: "cancelled" }).where(eq(bookingsTable.id, booking.id));
1105	        await db.update(gamesTable).set({ status: "cancelling" }).where(eq(gamesTable.id, game.id));
1106	
1107	        // Refund each paid participant via their session's payment intent
1108	        const paidParticipants = participants.filter(p => p.paymentStatus === "paid" && p.stripeSessionId);
1109	        for (const p of paidParticipants) {
1110	          try {
1111	            const session = await stripe.checkout.sessions.retrieve(p.stripeSessionId!);
1112	            if (session.payment_intent) {
1113	              await stripe.refunds.create({ payment_intent: session.payment_intent as string });
1114	            }
1115	          } catch (refundErr) {
1116	            logger.error({ participantId: p.id, err: refundErr }, "guarantee refund failed");
1117	          }
1118	        }
1119	        processed++;
1120	      }
1121	    } catch (err) {
1122	      logger.error({ bookingId: booking.id, err }, "sweepHostGuarantees: unexpected error");
1123	    }
1124	  }
1125	
1126	  return processed;
1127	}
