95	function useCountdown(targetMs: number | null): string | null {
96	  const [label, setLabel] = useState<string | null>(null);
97	  useEffect(() => {
98	    if (targetMs === null) { setLabel(null); return; }
99	    const update = () => {
100	      const diff = targetMs - Date.now();
101	      if (diff <= 0) { setLabel("Laikas baigėsi"); return; }
102	      const h = Math.floor(diff / 3600000);
103	      const m = Math.floor((diff % 3600000) / 60000);
104	      const s = Math.floor((diff % 60000) / 1000);
105	      if (h > 0) setLabel(`${h} val. ${m} min.`);
106	      else if (m > 0) setLabel(`${m} min. ${s} sek.`);
107	      else setLabel(`${s} sek.`);
108	    };
109	    update();
110	    const id = setInterval(update, 1000);
111	    return () => clearInterval(id);
112	  }, [targetMs]);
113	  return label;
114	}
