151	          bookingData.courtId
152	            ? fetch(`${API}/courts/${bookingData.courtId}`).then(r => r.ok ? r.json() : null)
153	            : Promise.resolve(null),
154	          bookingData.isSplit
155	            ? fetch(`${API}/bookings/${bookingData.id}/split-status`).then(r => r.ok ? r.json() : null)
156	            : Promise.resolve(null),
157	        ]);
158	
159	        if (courtResult.status === "fulfilled" && courtResult.value) {
160	          setCourt(courtResult.value);
161	        }
162	        if (splitResult.status === "fulfilled" && splitResult.value) {
163	          setSplitStatus(splitResult.value);
164	        }
165	      } catch (err: any) {
166	        setError(err.message ?? "Klaida");
