179	    ? new Date(`${booking.date.split("T")[0]}T${booking.startTime}:00`).getTime() - 2 * 60 * 60 * 1000
180	    : null;
181	  const countdown = useCountdown(guaranteeDeadlineMs);
182	
183	  const handleCopyLink = async () => {
