480	                const end = date + "T" + booking.endTime.slice(0, 5).replace(":", "") + "00";
481	                const sportLabel = getSportLabel(booking.courtSport);
482	                const courtLabel = booking.courtName ?? "Kortas";
483	                const title = booking.facilityName
484	                  ? `${sportLabel} – ${courtLabel}, ${booking.facilityName}`
485	                  : `${sportLabel} – ${courtLabel}`;
486	                const addressParts = [
487	                  booking.courtAddress,
488	                  booking.courtCity,
489	                  "Lietuva",
490	                ].filter(Boolean);
491	                const location = addressParts.join(", ");
492	                const siteUrl = "https://korts.lt";
493	                const bookingUrl = `${siteUrl}/bookings/${booking.id}`;
494	                const details = [
