497	                  booking.facilityName ? `🏢 Objektas: ${booking.facilityName}` : null,
498	                  `⚽ Sportas: ${sportLabel}`,
499	                  `💶 Kaina: ${Number(booking.totalPrice).toFixed(2)} €`,
500	                  `🔗 Peržiūrėti: ${bookingUrl}`,
501	                ].filter(Boolean).join("\n");
502	                const url =
503	                  `https://calendar.google.com/calendar/render?action=TEMPLATE` +
504	                  `&text=${encodeURIComponent(title)}` +
505	                  `&dates=${start}/${end}` +
506	                  `&ctz=Europe%2FVilnius` +
507	                  `&details=${encodeURIComponent(details)}` +
