328	function useCountdown(targetMs: number | null): string | null {
329	  const [label, setLabel] = useState<string | null>(null);
330	  useEffect(() => {
331	    if (targetMs === null) return;
332	    const update = () => {
333	      const diff = targetMs - Date.now();
334	      if (diff <= 0) { setLabel("Laikas baigėsi"); return; }
335	      const h = Math.floor(diff / 3600000);
336	      const m = Math.floor((diff % 3600000) / 60000);
337	      const s = Math.floor((diff % 60000) / 1000);
338	      if (h > 0) setLabel(`${h} val. ${m} min.`);
339	      else if (m > 0) setLabel(`${m} min. ${s} sek.`);
340	      else setLabel(`${s} sek.`);
341	    };
342	    update();
343	    const id = setInterval(update, 1000);
344	    return () => clearInterval(id);
345	  }, [targetMs]);
346	  return label;
347	}
