543	  })();
544	  const startMs = (b: typeof sorted[number]) => {
545	    // b.date is a Zod-coerced Date (UTC midnight). Use format() to get the
546	    // locale-safe yyyy-MM-dd string, then combine with end time for comparison.
547	    const dateStr = format(b.date, "yyyy-MM-dd");
