input.new_string:
// Defensive override: treat any unresolved booking (pending or awaiting_players)
// whose game start has already passed as failed — covers both sweeper misses and
// abandoned host checkouts (pending split with no confirmation).
const gameStartMs = new Date(`${dateLabel}T${booking.startTime}:00`).getTime();
const isZombieBooking = (booking.status === "awaiting_players" || booking.status === "pending")
  && Date.now() > gameStartMs;

