2	import app from "./app";
3	import { logger } from "./lib/logger";
4	import { startCron } from "./lib/cron";
5	
6	// Fail fast if the Clerk secret key is missing — every authenticated request
7	// will return 401 without it, and the error is completely silent otherwise.
8	if (!process.env.CLERK_SECRET_KEY) {
9	  logger.error(
10	    "CLERK_SECRET_KEY is not set — all authenticated API requests will return 401. " +
11	    "Set this to the sk_live_... key from the Clerk dashboard.",
12	  );
13	}
14	
15	if (!process.env.STRIPE_SECRET_KEY) {
16	  logger.warn(
17	    "STRIPE_SECRET_KEY is not set — Stripe routes will return 503 until configured.",
18	  );
19	}
20	
21	const rawPort = process.env["PORT"];
22	
23	if (!rawPort) {
24	  throw new Error("PORT environment variable is required but was not provided.");
25	}
26	
27	const port = Number(rawPort);
28	
29	if (Number.isNaN(port) || port <= 0) {
30	  throw new Error(`Invalid PORT value: "${rawPort}"`);
31	}
32	
33	// Wait for the port to become free before binding (handles rapid restarts where
34	// the previous process hasn't released the socket yet).
35	async function waitForPort(p: number, maxWaitMs = 10000): Promise<void> {
36	  const start = Date.now();
37	  while (Date.now() - start < maxWaitMs) {
38	    const free = await new Promise<boolean>((resolve) => {
39	      const tester = net.createConnection(p, "127.0.0.1");
40	      tester.once("connect", () => { tester.destroy(); resolve(false); });
41	      tester.once("error", () => resolve(true));
