1	import { Router, type IRouter } from "express";
2	import { desc, eq, or, and, sql, inArray } from "drizzle-orm";
3	import { db, directMessagesTable, notificationsTable, userProfilesTable } from "@workspace/db";
4	import { requireAuth, getCurrentUserId } from "../lib/auth";
5	
6	const router: IRouter = Router();
7	
8	function formatMsg(r: typeof directMessagesTable.$inferSelect) {
9	  return {
10	    ...r,
11	    createdAt: r.createdAt.toISOString(),
12	    readAt: r.readAt ? r.readAt.toISOString() : null,
13	  };
14	}
15	
16	// GET /dm/threads — list my conversations, grouped by "other user"
17	router.get("/dm/threads", requireAuth, async (req, res): Promise<void> => {
18	  const userId = getCurrentUserId(req)!;
19	
20	  const rows = await db.select().from(directMessagesTable)
21	    .where(or(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, userId)))
22	    .orderBy(desc(directMessagesTable.createdAt));
23	
24	  const threadMap = new Map<string, {
25	    otherUserId: string;
26	    otherUserName: string;
27	    lastMessage: ReturnType<typeof formatMsg>;
28	    unread: number;
29	  }>();
30	
31	  for (const r of rows) {
32	    const otherUserId = r.senderUserId === userId ? r.recipientUserId : r.senderUserId;
33	    const existing = threadMap.get(otherUserId);
34	    const isIncoming = r.recipientUserId === userId;
35	    const isUnread = isIncoming && !r.readAt;
36	    if (!existing) {
37	      threadMap.set(otherUserId, {
38	        otherUserId,
39	        otherUserName: r.senderUserId === userId ? "—" : r.senderName,
40	        lastMessage: formatMsg(r),
41	        unread: isUnread ? 1 : 0,
42	      });
43	    } else if (isUnread) {
44	      existing.unread += 1;
45	    }
46	  }
47	
48	  // Fill in names for threads where the latest message is from me
49	  for (const thread of threadMap.values()) {
50	    if (thread.otherUserName === "—") {
51	      const fromOther = rows.find(r => r.senderUserId === thread.otherUserId);
52	      if (fromOther) thread.otherUserName = fromOther.senderName;
53	      else thread.otherUserName = "Vartotojas";
54	    }
55	  }
56	
57	  // Fetch avatars for all other users from userProfilesTable
58	  const otherIds = [...threadMap.keys()];
59	  const imageMap = new Map<string, string | null>();
60	  if (otherIds.length > 0) {
61	    const profiles = await db
62	      .select({ userId: userProfilesTable.userId, imageUrl: userProfilesTable.imageUrl })
63	      .from(userProfilesTable)
64	      .where(inArray(userProfilesTable.userId, otherIds));
65	    for (const p of profiles) imageMap.set(p.userId, p.imageUrl);
66	  }
67	
68	  const threads = [...threadMap.values()].map(t => ({
69	    ...t,
70	    otherUserImageUrl: imageMap.get(t.otherUserId) ?? null,
71	  }));
72	
73	  res.json(threads);
74	});
75	
76	// GET /dm/thread/:otherUserId — all messages between me and otherUserId
77	router.get("/dm/thread/:otherUserId", requireAuth, async (req, res): Promise<void> => {
78	  const userId = getCurrentUserId(req)!;
79	  const otherUserId = String(req.params.otherUserId);
80	
81	  const rows = await db.select().from(directMessagesTable)
82	    .where(or(
83	      and(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, otherUserId)),
84	      and(eq(directMessagesTable.senderUserId, otherUserId), eq(directMessagesTable.recipientUserId, userId)),
85	    ))
86	    .orderBy(directMessagesTable.createdAt);
87	
88	  // Mark incoming messages as read
89	  await db.update(directMessagesTable).set({ readAt: new Date() })
90	    .where(and(
91	      eq(directMessagesTable.senderUserId, otherUserId),
92	      eq(directMessagesTable.recipientUserId, userId),
93	      sql`${directMessagesTable.readAt} IS NULL`,
94	    ));
95	
96	  res.json(rows.map(formatMsg));
97	});
98	
99	// POST /dm/send — send a direct message
100	router.post("/dm/send", requireAuth, async (req, res): Promise<void> => {
101	  const userId = getCurrentUserId(req)!;
102	  const { senderName, recipientUserId, body, contextType, contextId } = req.body ?? {};
103	  if (!senderName || !recipientUserId || !body) {
104	    res.status(400).json({ error: "senderName, recipientUserId, body required" }); return;
105	  }
106	
107	  const [msg] = await db.insert(directMessagesTable).values({
108	    senderUserId: userId,
109	    senderName,
110	    recipientUserId,
111	    body,
112	    contextType: contextType ?? null,
113	    contextId: contextId ?? null,
114	  }).returning();
115	
116	  // Notification for recipient
117	  await db.insert(notificationsTable).values({
118	    userId: recipientUserId,
119	    type: "message",
