function ChatBubbleInner() {
  const { user } = useUser();
  const { getToken } = useAuth();
  const qc = useQueryClient();
  const [open, setOpen] = useState(false);
  const [tab, setTab] = useState<"people" | "games">("people");
  const [active, setActive] = useState<{ userId: string; userName: string; imageUrl?: string | null; ctxType?: string; ctxId?: number } | null>(null);
  const [activeGame, setActiveGame] = useState<MyGame | null>(null);

  const { data: threads, isLoading: threadsLoading } = useQuery<Thread[]>({
    queryKey: ["dm-threads"],
    queryFn: () => customFetch<Thread[]>(`${API}/dm/threads`),
    enabled: !!user,
    staleTime: 60_000,
  });

  const { data: myGames, isLoading: gamesLoading } = useQuery<MyGame[]>({
    queryKey: ["my-games-chat"],
    queryFn: () => customFetch<MyGame[]>(`${API}/games/my`),
    enabled: !!user && open,
    staleTime: 60_000,
  });

  const { data: unread } = useQuery<{ count: number }>({
    queryKey: ["dm-unread"],
    queryFn: () => customFetch<{ count: number }>(`${API}/dm/unread-count`),
    enabled: !!user,
    staleTime: 60_000,
  });

  // ── Socket lifecycle ────────────────────────────────────────────────────────
  // ChatBubble is always mounted for signed-in users, so it owns the socket
  // connection lifetime. Other pages (messages.tsx) reuse the same singleton.
  useEffect(() => {
    if (!user) return;
    const socket = getSocket();

    (async () => {
      const token = await getToken();
      socket.auth = { token: token ?? "", userId: user.id };
      if (!socket.connected) socket.connect();
    })();

    const onNewMessage = (data: { type: "dm" | "game" | "facility"; message: any }) => {
      if (data.type === "dm") {
        const msg = data.message as DM;
        const otherId = msg.senderUserId === user.id ? msg.recipientUserId : msg.senderUserId;
        // Append to the thread cache if it's already loaded (avoid duplicate ids)
        qc.setQueryData<DM[]>(["dm", otherId], (old) => {
          if (!old) return old;
          if (old.some((m) => m.id === msg.id)) return old;
          return [...old, msg];
        });
        // If incoming from someone else, refresh the thread list sidebar
        if (msg.senderUserId !== user.id) {
          qc.invalidateQueries({ queryKey: ["dm-threads"] });
        }
      } else if (data.type === "game") {
        const msg = data.message as GameChatMsg;
        qc.setQueryData<GameChatMsg[]>(["game-chat", msg.gameId], (old) => {
          if (!old) return old;
          if (old.some((m) => m.id === msg.id)) return old;
          return [...old, msg];
        });
      }
    };

    const onUnreadUpdate = () => {
      qc.invalidateQueries({ queryKey: ["dm-unread"] });
      qc.invalidateQueries({ queryKey: ["dm-threads"] });
    };

    socket.on("new_message", onNewMessage);
    socket.on("unread_update", onUnreadUpdate);

    return () => {
      socket.off("new_message", onNewMessage);
      socket.off("unread_update", onUnreadUpdate);
      // Disconnect when the user signs out (user becomes null on next render)
    };
  }, [user?.id, getToken, qc]);

