import { useState, useEffect, useRef, useMemo } from "react";
import { useParams } from "wouter";
import { useUser } from "@clerk/react";
import { format, parseISO } from "date-fns";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { customFetch } from "@workspace/api-client-react";
import { OwnerLayout } from "@/components/owner-layout";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import {
  ArrowLeft,
  Calendar,
  Loader2,
  MessageSquare,
  Send,
} from "lucide-react";

const BASE_URL = import.meta.env.BASE_URL.replace(/\/$/, "");
const API_URL = `${BASE_URL}/api`;

interface FacilityData {
  id: number;
  name: string;
  ownerUserId?: string;
}

interface CourtSummary {
  id: number;
  facilityId?: number | null;
}

function useIsDesktop() {
  const [isDesktop, setIsDesktop] = useState(() =>
    typeof window === "undefined"
      ? true
      : window.matchMedia("(min-width: 768px)").matches,
  );
  useEffect(() => {
    if (typeof window === "undefined") return;
    const mq = window.matchMedia("(min-width: 768px)");
    const onChange = (e: MediaQueryListEvent) => setIsDesktop(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return isDesktop;
}

interface LatestBooking {
  id: number;
  date: string;
  startTime: string;
  endTime: string;
  status: string;
}

interface OwnerThread {
  courtId: number;
  courtName: string;
  threadUserId: string;
  threadUserName: string;
  threadUserImageUrl: string | null;
  latestBooking: LatestBooking | null;
  lastMessage: { body: string; senderUserId: string; createdAt: string };
}

interface OwnerMsg {
  id: number;
  senderUserId: string;
  senderName: string;
  body: string;
  createdAt: string;
}

function threadKey(t: OwnerThread) {
  return `${t.courtId}__${t.threadUserId}`;
}

function messagesQueryKey(courtId: number, threadUserId: string) {
  return ["owner-court-messages", courtId, threadUserId] as const;
}

function ThreadList({
  threads,
  selectedKey,
  loading,
  onSelect,
}: {
  threads: OwnerThread[];
  selectedKey: string | null;
  loading: boolean;
  onSelect: (t: OwnerThread) => void;
}) {
  if (loading) {
    return (
      <div className="p-3 space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-16 w-full rounded-lg" />

content.content:
