338	export default function OwnerFacilityMessages() {
339	  const { id } = useParams<{ id: string }>();
340	  const facilityId = Number(id);
341	  const { user } = useUser();
342	  const isDesktop = useIsDesktop();
343	  const [selectedKey, setSelectedKey] = useState<string | null>(null);
344	
345	  const { data: facility } = useQuery<FacilityData>({
346	    queryKey: ["facility-detail", id],
347	    queryFn: () => customFetch<FacilityData>(`${API_URL}/facilities/${id}`),
348	    enabled: !Number.isNaN(facilityId),
349	  });
350	
351	  // Owner-scoped court list (so unverified / pending courts in this facility
352	  // are included). Bypasses the typed listCourts hook because its codegen
353	  // params don't currently expose ownerUserId.
354	  const facilityOwnerId = facility?.ownerUserId;
355	  const { data: courts } = useQuery<CourtSummary[]>({
356	    queryKey: ["owner-courts", facilityOwnerId],
357	    queryFn: () =>
358	      customFetch<CourtSummary[]>(
359	        `${API_URL}/courts?ownerUserId=${encodeURIComponent(facilityOwnerId!)}`,
360	      ),
361	    enabled: !!facilityOwnerId,
362	  });
363	
364	  const facilityCourtIds = useMemo(() => {
365	    if (!courts) return new Set<number>();
366	    return new Set(
367	      courts.filter((c) => c.facilityId === facilityId).map((c) => c.id),
368	    );
369	  }, [courts, facilityId]);
370	
371	  const { data: allThreads, isLoading: threadsLoading } = useQuery<OwnerThread[]>({
372	    queryKey: ["owner-inbox"],
373	    queryFn: () => customFetch<OwnerThread[]>(`${API_URL}/messages/owner-inbox`),
374	  });
375	
376	  const threads = useMemo(() => {
377	    if (!allThreads) return [];
378	    if (facilityCourtIds.size === 0) return [];
379	    return allThreads.filter((t) => facilityCourtIds.has(t.courtId));
380	  }, [allThreads, facilityCourtIds]);
381	
382	  const selectedThread = useMemo(
383	    () => threads.find((t) => threadKey(t) === selectedKey) ?? null,
384	    [threads, selectedKey],
385	  );
386	
387	  // Auto-select the first thread only on desktop, and only once after threads
388	  // first arrive — so on mobile the user lands on the list, and pressing
389	  // "back" doesn't immediately re-open the first thread.
390	  const autoSelectedRef = useRef(false);
391	  useEffect(() => {
392	    if (
393	      isDesktop &&
394	      !autoSelectedRef.current &&
395	      !selectedKey &&
396	      threads.length > 0
397	    ) {
398	      autoSelectedRef.current = true;
399	      setSelectedKey(threadKey(threads[0]));
400	    }
401	  }, [isDesktop, threads, selectedKey]);
402	
403	  const ownerUserId = user?.id ?? "";
404	  const ownerName =
405	    user?.fullName ??
406	    user?.firstName ??
407	    user?.primaryEmailAddress?.emailAddress ??
408	    "Savininkas";
409	  const ownerEmail = user?.primaryEmailAddress?.emailAddress ?? "";
410	
411	  return (
412	    <OwnerLayout
413	      facilityId={facilityId}
414	      facilityName={facility?.name}
415	      title="Žinutės"
416	    >
417	      {/*
418	        Fill the entire OwnerLayout main column. OwnerLayout already spans the
419	        viewport minus the global topbar (4rem) and, on mobile, also injects a
420	        12px (h-12 = 3rem) facility header. Using flex-1 + min-h-0 inside that
421	        column makes us fit the remaining space exactly on both breakpoints.
422	      */}
423	      <div className="flex-1 min-h-0 flex flex-col">
424	        <div className="px-4 md:px-6 py-3 border-b bg-card shrink-0">
425	          <h1 className="text-xl font-semibold tracking-tight">Žinutės</h1>
426	          <p className="text-xs text-muted-foreground mt-0.5">
427	            Klientų pokalbiai apie šio objekto aikšteles.
428	          </p>
429	        </div>
430	        <div className="flex-1 min-h-0 grid grid-cols-1 md:grid-cols-[320px_1fr]">
431	          <aside
432	            className={`border-r bg-card overflow-y-auto ${
433	              selectedThread ? "hidden md:block" : "block"
434	            }`}
435	          >
436	            <ThreadList
437	              threads={threads}
438	              selectedKey={selectedKey}
439	              loading={threadsLoading}
440	              onSelect={(t) => setSelectedKey(threadKey(t))}
441	            />
442	          </aside>
443	          <section
444	            className={`min-h-0 ${selectedThread ? "block" : "hidden md:block"}`}
445	          >
446	            {selectedThread && ownerUserId ? (
447	              <OwnerChatPane
448	                key={threadKey(selectedThread)}
449	                thread={selectedThread}
450	                ownerUserId={ownerUserId}
451	                ownerName={ownerName}
452	                ownerEmail={ownerEmail}
453	                onBack={() => setSelectedKey(null)}
454	              />
455	            ) : (
456	              <div className="hidden md:flex flex-col items-center justify-center h-full text-muted-foreground text-sm gap-2 p-6 text-center">
457	                <MessageSquare className="w-10 h-10 opacity-20" />
458	                <p className="font-medium">Pasirinkite pokalbį</p>
459	                <p className="text-xs">
460	                  Kairėje pasirinkite klientą, kad peržiūrėtumėte žinutes.
461	                </p>
