23	function playChime() {
24	  try {
25	    if (typeof window === "undefined") return;
26	    const AC = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext | undefined;
27	    if (!AC) return;
28	    if (!audioCtx) audioCtx = new AC();
29	    const ctx = audioCtx;
30	    const now = ctx.currentTime;
31	    const gain = ctx.createGain();
32	    gain.gain.setValueAtTime(0.0001, now);
33	    gain.gain.exponentialRampToValueAtTime(0.18, now + 0.015);
34	    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.45);
35	    gain.connect(ctx.destination);
36	    const notes = [880, 1175];
37	    notes.forEach((freq, i) => {
38	      const osc = ctx.createOscillator();
39	      osc.type = "sine";
40	      osc.frequency.setValueAtTime(freq, now + i * 0.08);
41	      osc.connect(gain);
42	      osc.start(now + i * 0.08);
43	      osc.stop(now + i * 0.08 + 0.25);
44	    });
45	  } catch { /* ignore */ }
46	}
