371	    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
372	  }, [messages]);
373	
374	  const send = useMutation({
375	    mutationFn: () => customFetch(`${API}/games/${game.id}/chat`, {
376	      method: "POST", headers: { "Content-Type": "application/json" },
377	      body: JSON.stringify({
378	        senderName: user?.fullName || user?.firstName || "Vartotojas",
379	        body: text.trim(),
380	      }),
381	    }),
382	    onSuccess: () => {
383	      setText("");
384	      qc.invalidateQueries({ queryKey: ["game-chat", game.id] });
385	    },
386	    onError: (e: any) => toast({ title: "Nepavyko siųsti", description: e?.message, variant: "destructive" }),
387	  });
388	
389	  const sportBg = sportColor[game.sport] ?? "#6b7280";
390	
391	  return (
392	    <div className="flex flex-col h-full min-h-0">
393	      <div className="border-b border-border shrink-0">
394	        <div className="p-3 flex items-center gap-2">
395	          <Button variant="ghost" size="icon" className="h-8 w-8 -ml-1" onClick={onBack} aria-label="Atgal">
396	            <ArrowLeft className="w-4 h-4"/>
397	          </Button>
398	          <div
399	            className="h-9 w-9 rounded-full flex items-center justify-center shrink-0 text-white"
400	            style={{ backgroundColor: sportBg }}
401	          >
402	            <SportIcon sport={game.sport} className="w-4 h-4" />
403	          </div>
404	          <div className="min-w-0 flex-1">
405	            <div className="font-semibold text-sm truncate">
406	              {sportLabel(game.sport)} · {game.placeName ?? game.city}
407	            </div>
408	            <div className="text-[11px] text-muted-foreground flex items-center gap-1">
409	              <UsersIcon className="w-3 h-3" />
410	              {game.participants.length}/{game.playersNeeded} dalyvių
411	            </div>
412	          </div>
413	        </div>
414	        <Link
415	          href={`/matches/${game.id}`}
416	          className="block px-3 pb-2 -mt-1"
417	        >
418	          <div className="inline-flex items-center gap-1.5 text-[11px] font-medium bg-primary/10 text-primary px-2 py-1 rounded-md hover:bg-primary/15 transition-colors max-w-full">
419	            <CalendarDays className="w-3 h-3 shrink-0" />
420	            <span className="truncate">{formatGameWhen(game.datetime)}</span>
421	            <ExternalLink className="w-3 h-3 shrink-0 opacity-70" />
422	          </div>
423	        </Link>
424	      </div>
425	
426	      <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 space-y-2 min-h-0">
427	        {isLoading ? (
428	          <div className="space-y-2">
429	            <Skeleton className="h-10 w-2/3"/>
430	            <Skeleton className="h-10 w-1/2 ml-auto"/>
431	          </div>
432	        ) : (messages ?? []).length === 0 ? (
433	          <div className="text-center py-10 text-muted-foreground">
434	            <MessageSquare className="w-8 h-8 mx-auto mb-2 opacity-50"/>
435	            <p className="text-xs">Dar nėra žinučių. Pradėkite pokalbį!</p>
436	          </div>
437	        ) : (
438	          (messages ?? []).map((m) => {
439	            const isMine = m.senderUserId === user?.id;
440	            return (
441	              <div key={m.id} className={`flex ${isMine ? "justify-end" : "justify-start"}`}>
442	                <div className={`max-w-[78%] rounded-2xl px-3 py-2 ${
443	                  isMine
444	                    ? "bg-primary text-primary-foreground rounded-br-md"
445	                    : "bg-muted rounded-bl-md"
446	                }`}>
447	                  {!isMine && (
448	                    <div className="text-[10px] font-semibold text-muted-foreground mb-0.5">
449	                      {m.senderName}
450	                    </div>
451	                  )}
452	                  <p className="text-sm whitespace-pre-wrap break-words">{m.body}</p>
453	                  <div className={`text-[10px] mt-0.5 ${isMine ? "text-primary-foreground/70" : "text-muted-foreground"}`}>
454	                    {timeAgo(m.createdAt)}
455	                  </div>
456	                </div>
457	              </div>
458	            );
459	          })
460	        )}
461	      </div>
462	
463	      <form
464	        className="border-t border-border p-2 flex items-center gap-2 shrink-0"
465	        onSubmit={(e) => { e.preventDefault(); if (text.trim() && !send.isPending) send.mutate(); }}
466	      >
467	        <Input
468	          placeholder="Parašykite žinutę grupei..."
469	          value={text}
470	          onChange={(e) => setText(e.target.value)}
471	          className="flex-1 h-9"
472	          autoFocus
473	        />
474	        <Button type="submit" size="icon" className="h-9 w-9 shrink-0" disabled={!text.trim() || send.isPending}>
475	          <Send className="w-4 h-4"/>
476	        </Button>
477	      </form>
478	    </div>
479	  );
480	}
481	
482	function GameThreadsList({
483	  games, isLoading, onPick,
484	}: {
485	  games: MyGame[] | undefined;
486	  isLoading: boolean;
487	  onPick: (g: MyGame) => void;
488	}) {
489	  const upcoming = [...(games ?? [])]
490	    .filter(g => g.status !== "cancelled" && g.status !== "completed")
