500	          <UsersIcon className="w-10 h-10 mx-auto mb-2 opacity-50"/>
501	          <p className="text-sm font-medium">Nėra aktyvių žaidimų</p>
502	          <p className="text-xs mt-1">Prisijunkite prie žaidimo, kad galėtumėte rašyti grupei.</p>
503	        </div>
504	      ) : (
