510	                key={g.id}
511	                onClick={() => onPick(g)}
512	                className="w-full text-left p-3 flex gap-3 border-b border-border/60 hover:bg-muted/40 transition-colors"
513	              >
514	                <div
515	                  className="h-10 w-10 rounded-full flex items-center justify-center shrink-0 text-white"
516	                  style={{ backgroundColor: sportBg }}
517	                >
518	                  <SportIcon sport={g.sport} className="w-4 h-4" />
519	                </div>
520	                <div className="flex-1 min-w-0">
521	                  <div className="flex items-center justify-between gap-2">
522	                    <div className="font-semibold text-sm truncate">
523	                      {sportLabel(g.sport)} · {g.placeName ?? g.city}
524	                    </div>
525	                    <div className="text-[10px] text-muted-foreground shrink-0">
526	                      {g.participants.length}/{g.playersNeeded}
527	                    </div>
528	                  </div>
529	                  <div className="flex items-center gap-1 mt-0.5 text-xs text-muted-foreground truncate">
530	                    <CalendarDays className="w-3 h-3 shrink-0" />
531	                    <span className="truncate">{formatGameWhen(g.datetime)}</span>
532	                  </div>
533	                </div>
534	              </button>
535	            );
536	          })}
537	        </div>
538	      )}
539	    </div>
540	  );
541	}
542	
543	function ChatThreadsList({
544	  threads, isLoading, currentUserId, onPick,
545	}: {
546	  threads: Thread[] | undefined;
547	  isLoading: boolean;
548	  currentUserId?: string;
549	  onPick: (t: Thread) => void;
550	}) {
551	  return (
552	    <div className="flex-1 overflow-y-auto">
553	      {isLoading ? (
554	        <div className="p-3 space-y-2">
555	          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-14"/>)}
556	        </div>
557	      ) : !threads || threads.length === 0 ? (
558	        <div className="p-6 text-center text-muted-foreground">
559	          <MessageSquare className="w-10 h-10 mx-auto mb-2 opacity-50"/>
560	          <p className="text-sm font-medium">Kol kas nėra pokalbių</p>
561	          <p className="text-xs mt-1">Parašykite žinutę iš žaidimo arba aikštelės puslapio.</p>
562	        </div>
563	      ) : (
564	        <div>
565	          {threads.map((t) => {
566	            const isMatch = t.lastMessage.contextType === "game";
567	            return (
568	              <button
569	                key={t.otherUserId}
570	                onClick={() => onPick(t)}
571	                className="w-full text-left p-3 flex gap-3 border-b border-border/60 hover:bg-muted/40 transition-colors"
572	              >
573	                {isMatch ? (
574	                  <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
575	                    <Trophy className="w-4 h-4 text-primary" />
576	                  </div>
577	                ) : (
578	                  <Avatar className="h-10 w-10 shrink-0">
579	                    {t.otherUserImageUrl && <AvatarImage src={t.otherUserImageUrl} alt={t.otherUserName} />}
580	                    <AvatarFallback className="bg-primary/15 text-primary font-semibold text-xs">
581	                      {initials(t.otherUserName)}
582	                    </AvatarFallback>
583	                  </Avatar>
584	                )}
585	                <div className="flex-1 min-w-0">
586	                  <div className="flex items-center justify-between gap-2">
587	                    <div className="flex items-center gap-1.5 min-w-0">
588	                      <div className="font-semibold text-sm truncate">{t.otherUserName}</div>
589	                      {isMatch && (
590	                        <span className="text-[10px] bg-muted px-1.5 py-0.5 rounded-full shrink-0 text-muted-foreground font-medium">
591	                          Mačas
592	                        </span>
593	                      )}
594	                    </div>
595	                    <div className="text-[10px] text-muted-foreground shrink-0">{timeAgo(t.lastMessage.createdAt)}</div>
596	                  </div>
597	                  <div className="flex items-center justify-between gap-2 mt-0.5">
598	                    <div className={`text-xs truncate ${t.unread > 0 ? "font-semibold" : "text-muted-foreground"}`}>
599	                      {t.lastMessage.senderUserId === currentUserId ? "Jūs: " : ""}{t.lastMessage.body}
600	                    </div>
601	                    {t.unread > 0 && (
602	                      <Badge className="h-5 min-w-5 px-1.5 shrink-0 bg-red-500 hover:bg-red-500 text-white">
603	                        {t.unread}
604	                      </Badge>
605	                    )}
