617	function ChatBubbleInner() {
618	  const { user } = useUser();
619	  const { getToken } = useAuth();
620	  const qc = useQueryClient();
621	  const [open, setOpen] = useState(false);
622	  const [tab, setTab] = useState<"people" | "games">("people");
623	  const [active, setActive] = useState<{ userId: string; userName: string; imageUrl?: string | null; ctxType?: string; ctxId?: number } | null>(null);
624	  const [activeGame, setActiveGame] = useState<MyGame | null>(null);
625	
626	  const { data: threads, isLoading: threadsLoading } = useQuery<Thread[]>({
627	    queryKey: ["dm-threads"],
628	    queryFn: () => customFetch<Thread[]>(`${API}/dm/threads`),
629	    enabled: !!user,
630	    staleTime: 60_000,
631	  });
632	
633	  const { data: myGames, isLoading: gamesLoading } = useQuery<MyGame[]>({
634	    queryKey: ["my-games-chat"],
635	    queryFn: () => customFetch<MyGame[]>(`${API}/games/my`),
636	    enabled: !!user && open,
637	    staleTime: 60_000,
638	  });
639	
640	  const { data: unread } = useQuery<{ count: number }>({
641	    queryKey: ["dm-unread"],
642	    queryFn: () => customFetch<{ count: number }>(`${API}/dm/unread-count`),
643	    enabled: !!user,
644	    staleTime: 60_000,
645	  });
646	
647	  // ── Socket lifecycle ────────────────────────────────────────────────────────
648	  // ChatBubble is always mounted for signed-in users, so it owns the socket
649	  // connection lifetime. Other pages (messages.tsx) reuse the same singleton.
650	  useEffect(() => {
651	    if (!user) return;
652	    const socket = getSocket();
653	
654	    (async () => {
655	      const token = await getToken();
656	      socket.auth = { token: token ?? "", userId: user.id };
657	      if (!socket.connected) socket.connect();
658	    })();
659	
660	    const onNewMessage = (data: { type: "dm" | "game" | "facility"; message: any }) => {
661	      if (data.type === "dm") {
662	        const msg = data.message as DM;
663	        const otherId = msg.senderUserId === user.id ? msg.recipientUserId : msg.senderUserId;
664	        // Append to the thread cache if it's already loaded (avoid duplicate ids)
665	        qc.setQueryData<DM[]>(["dm", otherId], (old) => {
666	          if (!old) return old;
667	          if (old.some((m) => m.id === msg.id)) return old;
668	          return [...old, msg];
669	        });
670	        // If incoming from someone else, refresh the thread list sidebar
671	        if (msg.senderUserId !== user.id) {
672	          qc.invalidateQueries({ queryKey: ["dm-threads"] });
673	        }
674	      } else if (data.type === "game") {
675	        const msg = data.message as GameChatMsg;
676	        qc.setQueryData<GameChatMsg[]>(["game-chat", msg.gameId], (old) => {
677	          if (!old) return old;
678	          if (old.some((m) => m.id === msg.id)) return old;
679	          return [...old, msg];
680	        });
681	      }
682	    };
683	
684	    const onUnreadUpdate = () => {
685	      qc.invalidateQueries({ queryKey: ["dm-unread"] });
686	      qc.invalidateQueries({ queryKey: ["dm-threads"] });
687	    };
688	
689	    socket.on("new_message", onNewMessage);
690	    socket.on("unread_update", onUnreadUpdate);
691	
692	    return () => {
693	      socket.off("new_message", onNewMessage);
694	      socket.off("unread_update", onUnreadUpdate);
695	      // Disconnect when the user signs out (user becomes null on next render)
696	    };
697	  }, [user?.id, getToken, qc]);
698	
699	  const unreadCount = unread?.count ?? 0;
700	
701	  // Detect increases in unread count → play chime + browser notification
702	  const prevUnreadRef = useRef<number | null>(null);
703	  useEffect(() => {
704	    const prev = prevUnreadRef.current;
705	    if (prev !== null && unreadCount > prev) {
706	      playChime();
707	      // Pick latest unread thread for preview text
708	      const latest = threads?.find(t => t.unread > 0);
709	      if (latest) {
710	        showBrowserNotification(
711	          `${latest.otherUserName} · Nauja žinutė`,
712	          latest.lastMessage.body.slice(0, 140),
713	        );
714	      } else {
715	        showBrowserNotification("Nauja žinutė", "Atidarykite korts.lt, kad atsakytumėte.");
716	      }
717	    }
718	    prevUnreadRef.current = unreadCount;
719	  }, [unreadCount, threads]);
720	
721	  // Ask for notification permission the first time the user opens the bubble
722	  const askedPermRef = useRef(false);
723	  useEffect(() => {
724	    if (open && !askedPermRef.current) {
725	      askedPermRef.current = true;
726	      requestNotificationPermission();
727	    }
728	  }, [open]);
729	
730	  // Listen for global "open chat" events dispatched from other pages
731	  useEffect(() => {
732	    const handler = (e: Event) => {
733	      const ev = e as CustomEvent<OpenChatDetail>;
734	      if (!ev.detail?.userId) return;
735	      setActive({
736	        userId: ev.detail.userId,
737	        userName: ev.detail.userName,
738	        ctxType: ev.detail.ctxType,
739	        ctxId: ev.detail.ctxId,
740	      });
741	      setOpen(true);
742	    };
743	    window.addEventListener("korts:open-chat", handler);
744	    return () => window.removeEventListener("korts:open-chat", handler);
745	  }, []);
746	
747	  // Close on Escape
748	  useEffect(() => {
749	    if (!open) return;
750	    const onKey = (e: KeyboardEvent) => {
751	      if (e.key === "Escape") {
752	        if (active) setActive(null);
753	        else if (activeGame) setActiveGame(null);
754	        else setOpen(false);
755	      }
756	    };
757	    window.addEventListener("keydown", onKey);
758	    return () => window.removeEventListener("keydown", onKey);
759	  }, [open, active, activeGame]);
760	
761	  const toggle = useCallback(() => {
762	    setOpen(v => {
763	      if (v) {
764	        setActive(null);
765	        setActiveGame(null);
766	      }
767	      return !v;
768	    });
769	  }, []);
770	
771	  return (
772	    <>
773	      {/* Sticky bubble button */}
774	      <button
775	        onClick={toggle}
776	        aria-label={open ? "Uždaryti žinutes" : "Atidaryti žinutes"}
777	        className="fixed bottom-[5.5rem] right-4 sm:bottom-6 sm:right-6 z-[60] h-14 w-14 rounded-full bg-primary text-primary-foreground shadow-lg hover:shadow-xl hover:scale-105 active:scale-95 transition-all flex items-center justify-center focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
778	      >
779	        {open ? <X className="w-6 h-6"/> : <MessageCircle className="w-6 h-6"/>}
780	        {!open && unreadCount > 0 && (
781	          <span className="absolute -top-1 -right-1 min-w-5 h-5 px-1.5 rounded-full bg-red-500 text-white text-[11px] font-bold flex items-center justify-center shadow-md ring-2 ring-background">
782	            {unreadCount > 99 ? "99+" : unreadCount}
783	          </span>
784	        )}
785	      </button>
786	
787	      {/* Chat panel */}
788	      {open && (
789	        <div
790	          className="fixed z-[59] bg-card border border-border shadow-2xl overflow-hidden flex flex-col
791	            bottom-0 right-0 left-0 top-0 rounded-none
792	            sm:bottom-24 sm:right-6 sm:left-auto sm:top-auto sm:rounded-2xl sm:w-[380px] sm:h-[560px] sm:max-h-[calc(100dvh-8rem)]"
793	          role="dialog"
794	          aria-label="Žinutės"
795	        >
796	          <div className="border-b border-border p-3 flex items-center justify-between shrink-0 bg-primary/5">
797	            {active || activeGame ? (
798	              <div className="flex items-center gap-2 min-w-0">
799	                <MessageCircle className="w-4 h-4 text-primary shrink-0"/>
800	                <span className="font-semibold text-sm truncate">Pokalbis</span>
801	              </div>
802	            ) : (
803	              <div className="flex items-center gap-2">
804	                <MessageCircle className="w-4 h-4 text-primary"/>
805	                <span className="font-semibold text-sm">Žinutės</span>
806	                {unreadCount > 0 && (
807	                  <Badge className="h-5 min-w-5 px-1.5 bg-red-500 hover:bg-red-500 text-white">{unreadCount}</Badge>
808	                )}
809	              </div>
810	            )}
811	            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setOpen(false)} aria-label="Uždaryti">
812	              <X className="w-4 h-4"/>
813	            </Button>
814	          </div>
815	
816	          {active ? (
817	            <ChatThreadView
818	              otherUserId={active.userId}
819	              otherUserName={active.userName}
820	              otherUserImageUrl={active.imageUrl}
821	              ctxType={active.ctxType}
822	              ctxId={active.ctxId}
823	              onBack={() => setActive(null)}
824	            />
825	          ) : activeGame ? (
826	            <GameChatView
827	              game={activeGame}
828	              onBack={() => setActiveGame(null)}
829	            />
830	          ) : (
831	            <>
832	              <div className="border-b border-border flex shrink-0 bg-card">
833	                <button
834	                  onClick={() => setTab("people")}
835	                  className={`flex-1 py-2.5 text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 ${
836	                    tab === "people"
837	                      ? "text-primary border-b-2 border-primary"
838	                      : "text-muted-foreground hover:text-foreground border-b-2 border-transparent"
839	                  }`}
840	                >
841	                  <MessageSquare className="w-3.5 h-3.5"/> Žmonės
842	                  {unreadCount > 0 && (
843	                    <Badge className="h-4 min-w-4 px-1 ml-0.5 bg-red-500 hover:bg-red-500 text-white text-[10px]">{unreadCount}</Badge>
844	                  )}
845	                </button>
846	                <button
847	                  onClick={() => setTab("games")}
848	                  className={`flex-1 py-2.5 text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 ${
849	                    tab === "games"
850	                      ? "text-primary border-b-2 border-primary"
851	                      : "text-muted-foreground hover:text-foreground border-b-2 border-transparent"
852	                  }`}
853	                >
854	                  <UsersIcon className="w-3.5 h-3.5"/> Žaidimai
855	                </button>
856	              </div>
857	              {tab === "people" ? (
858	                <ChatThreadsList
859	                  threads={threads}
860	                  isLoading={threadsLoading}
861	                  currentUserId={user?.id}
862	                  onPick={(t) => setActive({ userId: t.otherUserId, userName: t.otherUserName, imageUrl: t.otherUserImageUrl })}
863	                />
864	              ) : (
865	                <GameThreadsList
866	                  games={myGames}
867	                  isLoading={gamesLoading}
868	                  onPick={(g) => setActiveGame(g)}
869	                />
870	              )}
871	            </>
872	          )}
873	        </div>
874	      )}
875	    </>
876	  );
877	}
878	
879	export function ChatBubble() {
880	  return (
881	    <Show when="signed-in">
882	      <ChatBubbleInner />
883	    </Show>
884	  );
885	}
