191	function ChatThreadView({
192	  otherUserId, otherUserName, otherUserImageUrl, ctxType, ctxId, onBack,
193	}: {
194	  otherUserId: string; otherUserName: string; otherUserImageUrl?: string | null;
195	  ctxType?: string; ctxId?: number;
196	  onBack: () => void;
197	}) {
198	  const { user } = useUser();
199	  const { toast } = useToast();
200	  const qc = useQueryClient();
201	  const [text, setText] = useState("");
202	  const scrollRef = useRef<HTMLDivElement>(null);
203	  const [profileOpen, setProfileOpen] = useState(false);
204	
205	  const { data: messages, isLoading } = useQuery<DM[]>({
206	    queryKey: ["dm", otherUserId],
207	    queryFn: () => customFetch<DM[]>(`${API}/dm/thread/${otherUserId}`),
208	    staleTime: 60_000,
209	  });
210	
211	  // Join the DM socket room whenever this conversation is opened
212	  useEffect(() => {
213	    getSocket().emit("join_rooms", { dmUserId: otherUserId });
214	  }, [otherUserId]);
215	
216	  // Prefer the latest message's context; fall back to opener's context
217	  const latestCtx = messages?.slice().reverse().find(m => m.contextType && m.contextId);
218	  const effectiveCtxType = latestCtx?.contextType ?? ctxType;
219	  const effectiveCtxId = latestCtx?.contextId ?? ctxId;
220	  const ctx = useContextInfo(effectiveCtxType ?? undefined, effectiveCtxId ?? undefined);
221	
222	  useEffect(() => {
223	    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
224	  }, [messages]);
225	
226	  useEffect(() => {
227	    // Opening a thread marks it read on the server (endpoint does this on fetch);
228	    // refresh unread badge.
229	    qc.invalidateQueries({ queryKey: ["dm-unread"] });
230	    qc.invalidateQueries({ queryKey: ["dm-threads"] });
231	  }, [otherUserId, messages?.length, qc]);
232	
