                    <CourtCard court={court} />
                  </div>
                ))}
              </DragScrollRow>
            ) : null}
          </div>
        </section>
      )}

      {/* Popular Courts */}
      <section className="py-8 md:py-14 bg-muted/30">
        <div className="container mx-auto px-4">
          <h2 className="text-2xl md:text-3xl font-bold mb-5 md:mb-8 tracking-tight">{t("home.popular.title")}</h2>
