560	      },
561	      { timeout: 8000, maximumAge: 60000 }
562	    );
563	  };
564	
565	  const visibleCourts = useMemo(() => {
566	    // Always exclude courts without valid coordinates — they would render at (0, 0)
567	    let list = (Array.isArray(courts) ? courts : []).filter(
568	      c => activeSports.has(c.type) && c.latitude != null && c.longitude != null
569	    );
570	    if (nearbyMode && userLocation) {
571	      list = list.filter(c => haversineKm(userLocation.lat, userLocation.lng, c.latitude!, c.longitude!) <= NEARBY_KM);
572	    }
573	    return list;
574	  }, [courts, activeSports, nearbyMode, userLocation]);
575	
576	  const { isLoaded, loadError } = useJsApiLoader({
577	    googleMapsApiKey: API_KEY ?? "",
578	    libraries: LIBRARIES,
579	  });
580	
581	  const fitBounds = useCallback((map: google.maps.Map, list: Court[]) => {
582	    if (list.length === 0) {
583	      map.setCenter(LITHUANIA_CENTER);
584	      map.setZoom(7);
585	    } else if (list.length === 1) {
586	      map.setCenter({ lat: list[0].latitude!, lng: list[0].longitude! });
587	      map.setZoom(13);
588	    } else {
589	      const bounds = new google.maps.LatLngBounds();
590	      list.forEach(c => bounds.extend({ lat: c.latitude!, lng: c.longitude! }));
591	      map.fitBounds(bounds, 60);
592	    }
593	  }, []);
594	
595	  const onLoad = useCallback((map: google.maps.Map) => {
596	    mapRef.current = map;
597	    // Build icon cache once Google Maps is ready
598	    iconCacheRef.current = buildIconCache();
599	    // Init clusterer
600	    clustererRef.current = new MarkerClusterer({
601	      map,
602	      markers: [],
603	      renderer: {
604	        render({ count, position }) {
605	          return new google.maps.Marker({
606	            position,
607	            label: {
608	              text: String(count),
609	              color: "#F3F7FA",
610	              fontSize: "12px",
611	              fontWeight: "700",
612	            },
613	            icon: {
614	              url: `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(
615	                `<svg xmlns="http://www.w3.org/2000/svg" width="42" height="42" viewBox="0 0 42 42">
616	                  <circle cx="21" cy="21" r="19" fill="#C5E041" stroke="#FFFFFF" stroke-width="2.5"/>
617	                </svg>`
618	              )}`,
619	              scaledSize: new google.maps.Size(42, 42),
620	              anchor: new google.maps.Point(21, 21),
621	            },
622	            zIndex: 1000,
623	          });
624	        },
625	      },
626	    });
627	    fitBounds(map, courts);
628	
629	    // Load Lithuania border and grey-out surrounding countries
630	    fetch("https://raw.githubusercontent.com/glynnbird/countriesgeojson/master/lithuania.geojson")
631	      .then(r => r.json())
632	      .then((geoJson: any) => {
633	        if (!mapRef.current) return;
634	        const feature = geoJson.features?.[0];
635	        if (!feature) return;
636	        const geom = feature.geometry;
637	        let outerRing: number[][];
638	        if (geom.type === "Polygon") {
639	          outerRing = geom.coordinates[0];
640	        } else if (geom.type === "MultiPolygon") {
641	          outerRing = geom.coordinates[0][0];
642	        } else return;
643	
644	        // World bounding box (counter-clockwise outer ring)
645	        const worldBbox = [[-180, -90], [180, -90], [180, 90], [-180, 90], [-180, -90]];
646	        // Lithuania ring reversed → clockwise hole
647	        const hole = [...outerRing].reverse();
648	
649	        map.data.addGeoJson({
650	          type: "FeatureCollection",
651	          features: [
652	            // Grey veil over everything outside Lithuania
653	            {
654	              type: "Feature",
655	              properties: { kind: "overlay" },
656	              geometry: { type: "Polygon", coordinates: [worldBbox, hole] },
657	            },
658	            // Lithuania border highlight
659	            {
660	              type: "Feature",
661	              properties: { kind: "border" },
662	              geometry: geom,
663	            },
664	          ],
665	        });
666	
667	        map.data.setStyle((f: google.maps.Data.Feature) => {
668	          const kind = f.getProperty("kind");
669	          if (kind === "overlay") {
670	            return { fillColor: "#132D4C", fillOpacity: 0.35, strokeOpacity: 0, clickable: false, zIndex: 1 };
671	          }
672	          if (kind === "border") {
673	            return { fillOpacity: 0, strokeColor: "#C5E041", strokeWeight: 1.5, strokeOpacity: 0.7, clickable: false, zIndex: 2 };
674	          }
675	          return {};
676	        });
677	      })
678	      .catch(() => { /* non-critical — map still works without overlay */ });
679	
680	    setMapReady(true);
681	  }, [courts, fitBounds]);
682	
683	  // Imperatively manage markers — no React component per marker
684	  useEffect(() => {
685	    if (!mapRef.current || !iconCacheRef.current || !clustererRef.current) return;
686	
687	    const map = mapRef.current;
688	    const icons = iconCacheRef.current;
689	    const clusterer = clustererRef.current;
690	    const visibleIds = new Set(visibleCourts.map(c => c.id));
691	    const currentIds = new Set(markersRef.current.keys());
692	
693	    // Remove markers no longer visible
694	    const toRemove: google.maps.Marker[] = [];
695	    for (const [id, marker] of markersRef.current.entries()) {
696	      if (!visibleIds.has(id)) {
697	        marker.setMap(null);
698	        toRemove.push(marker);
699	        markersRef.current.delete(id);
700	      }
701	    }
702	    if (toRemove.length) clusterer.removeMarkers(toRemove);
703	
704	    // Add new markers
705	    const toAdd: google.maps.Marker[] = [];
706	    for (const court of visibleCourts) {
707	      if (currentIds.has(court.id)) continue;
708	      const sportIcons = icons[court.type] ?? icons["tennis"];
709	      const marker = new google.maps.Marker({
710	        position: { lat: court.latitude!, lng: court.longitude! },
711	        icon: sportIcons.normal,
712	        title: court.name,
713	        zIndex: 1,
714	      });
715	      marker.addListener("click", () => {
716	        setSelectedCourt(prev => (prev?.id === court.id ? null : court));
717	      });
718	      markersRef.current.set(court.id, marker);
719	      toAdd.push(marker);
720	    }
721	    if (toAdd.length) clusterer.addMarkers(toAdd);
722	  }, [visibleCourts, mapReady]);
723	
724	  // Update selected marker icon when selection changes
725	  useEffect(() => {
726	    if (!iconCacheRef.current) return;
727	    const icons = iconCacheRef.current;
728	    for (const [id, marker] of markersRef.current.entries()) {
729	      const court = visibleCourts.find(c => c.id === id);
730	      if (!court) continue;
731	      const sportIcons = icons[court.type] ?? icons["tennis"];
732	      const isSelected = selectedCourt?.id === id;
733	      marker.setIcon(isSelected ? sportIcons.selected : sportIcons.normal);
734	      marker.setZIndex(isSelected ? 999 : 1);
735	    }
736	  }, [selectedCourt, visibleCourts]);
737	
738	  // Cleanup on unmount
739	  useEffect(() => {
740	    return () => {
741	      for (const marker of markersRef.current.values()) {
742	        marker.setMap(null);
743	      }
744	      markersRef.current.clear();
745	      clustererRef.current?.clearMarkers();
746	    };
747	  }, []);
748	
749	  // Update map styles when theme or mapType changes
