751	    if (!mapRef.current) return;
752	    const styles = mapType === "roadmap"
753	      ? (theme === "dark" ? MAP_STYLES_DARK : MAP_STYLES_LIGHT)
754	      : undefined;
755	    mapRef.current.setOptions({ styles });
756	  }, [theme, mapType]);
757	
758	  useEffect(() => {
759	    if (!mapRef.current || !nearbyMode || !userLocation || !userDotRef.current || !userMarkerRef.current) return;
760	    userDotRef.current.setPosition(userLocation);
761	    userMarkerRef.current.setCenter(userLocation);
762	  }, [nearbyMode, userLocation]);
763	
764	
765	  if (loadError || !API_KEY) {
766	    return (
767	      <div className="w-full h-full min-h-[400px] rounded-xl overflow-hidden border border-border/50 bg-muted flex flex-col items-center justify-center gap-4 p-6 text-center">
768	        <MapPin className="w-12 h-12 text-muted-foreground/30" />
769	        <div>
770	          <p className="font-semibold text-foreground mb-1">Google Maps nepasiekiamas</p>
771	          <p className="text-sm text-muted-foreground">
772	            {!API_KEY ? "Reikalingas VITE_GOOGLE_MAPS_API_KEY konfigūracijos raktas." : "Nepavyko įkelti žemėlapio."}
773	          </p>
774	        </div>
775	      </div>
776	    );
777	  }
778	
779	  if (!isLoaded) {
780	    return (
781	      <div className="w-full h-full min-h-[400px] rounded-xl overflow-hidden border border-border/50 bg-muted animate-pulse flex items-center justify-center">
782	        <div className="text-muted-foreground text-sm">Kraunamas žemėlapis...</div>
783	      </div>
784	    );
785	  }
786	
787	  return (
788	    <div className="w-full h-full min-h-[400px] z-0 relative rounded-xl overflow-hidden border border-border/50 shadow-sm">
