807	        )}
808	      </GoogleMap>
809	
810	      {/* Map / Satellite toggle */}
811	      <div className="absolute top-3 left-3 z-[1000] flex rounded-lg overflow-hidden border border-border shadow-md text-xs font-medium">
812	        {(["roadmap", "satellite"] as const).map(t => (
813	          <button
814	            key={t}
815	            onClick={() => setMapType(t)}
816	            className={`px-3 py-1.5 transition-colors ${
817	              mapType === t
