1	import { useState, useEffect, useRef, useCallback } from "react";
2	import { useUser, useAuth } from "@clerk/react";
3	import { Bell } from "lucide-react";
4	import {
5	  Popover,
6	  PopoverContent,
7	  PopoverTrigger,
8	} from "@/components/ui/popover";
9	import { useLocation } from "wouter";
10	import { useRole } from "@/lib/useRole";
11	
12	type Notif = {
13	  id: number;
14	  userId: string;
15	  type: string;
16	  title: string;
17	  body: string;
18	  link: string | null;
19	  read: boolean;
20	  createdAt: string;
21	};
22	
23	type TabId = "player" | "owner" | "coach";
24	
25	// Notification types that belong to owner context (business management)
26	const OWNER_TYPE_SET = new Set([
27	  "booking_created",
28	  "booking_cancelled",
29	  "court_approved",
30	  "court_rejected",
31	  "facility_approved",
32	  "facility_rejected",
33	  "coach_application",
34	  "tournament_pending_review",
35	  "tournament_approved",
36	  "tournament_rejected",
37	]);
38	
39	// Notification types that belong to coach context (career management)
40	const COACH_TYPE_SET = new Set([
41	  "coach_approved",
42	  "coach_rejected",
43	  "coach_invite",
44	  "court_coach_approved",
45	  "court_coach_rejected",
46	]);
47	
48	function getNotifAudience(n: Notif): TabId {
49	  const link = n.link ?? "";
50	  if (link.startsWith("/owner")) return "owner";
51	  if (link.startsWith("/coach")) return "coach";
52	  if (OWNER_TYPE_SET.has(n.type)) return "owner";
53	  if (COACH_TYPE_SET.has(n.type)) return "coach";
54	  return "player";
55	}
56	
57	function getDefaultTab(location: string, isOwner: boolean, isCoach: boolean): TabId {
58	  if (isOwner && location.startsWith("/owner")) return "owner";
59	  if (isCoach && location.startsWith("/coach/me")) return "coach";
60	  return "player";
61	}
62	
63	function timeAgo(iso: string) {
64	  const diff = Date.now() - new Date(iso).getTime();
65	  const mins = Math.floor(diff / 60000);
66	  if (mins < 1) return "ką tik";
67	  if (mins < 60) return `prieš ${mins} min`;
68	  const hrs = Math.floor(mins / 60);
69	  if (hrs < 24) return `prieš ${hrs} val`;
70	  const days = Math.floor(hrs / 24);
71	  return `prieš ${days} d`;
72	}
73	
74	function typeIcon(type: string) {
75	  switch (type) {
76	    case "message": return "💬";
77	    case "booking_created": return "📅";
78	    case "booking_cancelled": return "❌";
79	    case "court_approved": return "✅";
80	    case "court_rejected": return "🚫";
81	    case "facility_approved": return "✅";
82	    case "facility_rejected": return "🚫";
83	    case "coach_approved": return "✅";
84	    case "coach_rejected": return "🚫";
85	    case "coach_invite": return "👤";
86	    case "court_coach_approved": return "✅";
87	    case "court_coach_rejected": return "🚫";
88	    case "coach_application": return "📋";
89	    case "game_join_request": return "🏃";
90	    case "game_cancelled": return "🚫";
91	    case "game_join_approved": return "✅";
92	    case "game_join_rejected": return "🚫";
93	    case "game_removed": return "🚫";
94	    case "result_confirmation": return "🏆";
95	    case "result_disputed": return "⚠️";
96	    case "elo_update": return "📊";
97	    case "split_player_joined": return "👥";
98	    case "tournament_approved": return "✅";
99	    case "tournament_rejected": return "🚫";
100	    case "tournament_pending_review": return "🔔";
101	    case "admin_pending_review": return "🔔";
102	    default: return "🔔";
103	  }
104	}
105	
106	export function NotificationBell() {
107	  const { user, isSignedIn } = useUser();
108	  const { getToken } = useAuth();
109	  const { isAdmin, isOwner, isCoach } = useRole();
110	  const [notifs, setNotifs] = useState<Notif[]>([]);
111	  const [adminNotifs, setAdminNotifs] = useState<Notif[]>([]);
112	  const [open, setOpen] = useState(false);
113	  const [location, setLocation] = useLocation();
114	  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
115	
116	  const userId = user?.id ?? null;
117	
118	  // Derive per-tab notification lists
119	  const playerNotifs = notifs.filter(n => getNotifAudience(n) === "player");
120	  const ownerNotifs = [
121	    ...notifs.filter(n => getNotifAudience(n) === "owner"),
122	    ...adminNotifs,
123	  ].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
124	  const coachNotifs = notifs.filter(n => getNotifAudience(n) === "coach");
125	
126	  // Unread counts per tab and total
127	  const playerUnread = playerNotifs.filter(n => !n.read).length;
128	  const ownerUnread = ownerNotifs.filter(n => !n.read).length;
129	  const coachUnread = coachNotifs.filter(n => !n.read).length;
130	  const totalUnread = playerUnread + ownerUnread + coachUnread;
131	
132	  // Tabs — only show if user has more than just the player role
133	  const availableTabs: TabId[] = ["player"];
134	  if (isOwner) availableTabs.push("owner");
135	  if (isCoach) availableTabs.push("coach");
136	  const showTabs = availableTabs.length > 1;
137	
138	  const defaultTab = getDefaultTab(location, isOwner, isCoach);
139	  const [activeTab, setActiveTab] = useState<TabId>(defaultTab);
140	
141	  // Reset active tab each time the popover opens, based on current page
142	  useEffect(() => {
143	    if (open) setActiveTab(getDefaultTab(location, isOwner, isCoach));
