function WorkingHoursAccordion({ json }: { json: string }) {
  const [open, setOpen] = useState(false);
  let wh: Record<string, { open: string; close: string; closed: boolean }>;
  try { wh = JSON.parse(json); } catch { return null; }

  const todayDow = new Date().getDay();
  const todayCfg = wh[String(todayDow)];
  const hhmm = new Date().toTimeString().slice(0, 5);
  const isOpenNow = !!(todayCfg && !todayCfg.closed && hhmm >= todayCfg.open && hhmm < todayCfg.close);
  const todayHours = todayCfg?.closed ? "Nedirbama" : `${todayCfg?.open ?? "08:00"} – ${todayCfg?.close ?? "22:00"}`;

  return (
    <div>
      <h2 className="text-2xl font-semibold mb-3 flex items-center gap-3">
        <Clock className="w-6 h-6 text-primary" />
        Darbo laikas
        <span className={`text-xs font-medium px-2.5 py-1 rounded-full border ${isOpenNow ? "bg-green-500/10 text-green-600 border-green-400/30" : "bg-red-500/10 text-red-600 border-red-400/30"}`}>
          {isOpenNow ? "Atidaryta" : "Uždaryta"}
        </span>
      </h2>
      <Collapsible open={open} onOpenChange={setOpen}>
        <CollapsibleTrigger asChild>
          <button className="flex items-center justify-between w-full text-sm px-4 py-2.5 rounded-xl border border-border hover:bg-muted/40 transition-colors">
            <span className="flex items-center gap-2">
              <span className="font-medium text-foreground">Šiandien</span>
              <span className={`tabular-nums ${todayCfg?.closed ? "text-muted-foreground" : "text-primary font-semibold"}`}>
                {todayHours}
              </span>
            </span>
            <ChevronDown className={`w-4 h-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </button>
        </CollapsibleTrigger>
        <CollapsibleContent>
          <div className="mt-1 rounded-xl border border-border overflow-hidden">
            {WH_DAYS.map(({ dow, label }) => {
              const cfg = wh[String(dow)];
              const isToday = dow === todayDow;
              return (
                <div
                  key={dow}
                  className={`flex items-center justify-between px-4 py-1.5 border-b border-border last:border-b-0 text-sm ${isToday ? "bg-primary/5" : ""}`}
                >
                  <span className={`font-medium ${isToday ? "text-primary" : "text-foreground"}`}>{label}</span>
                  {cfg?.closed ? (
                    <span className="text-xs text-muted-foreground">Nedirbama</span>
                  ) : (
                    <span className={`tabular-nums ${isToday ? "text-primary font-semibold" : "text-muted-foreground"}`}>
                      {cfg?.open ?? "08:00"} – {cfg?.close ?? "22:00"}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </CollapsibleContent>
      </Collapsible>
    </div>
  );
}

